-- =============================================================================
-- OneRoboLab — seed data (run once, after schema.sql, on a fresh database)
--
--   psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f database/seed.sql
--
-- SECURITY: every account below uses the placeholder password hash
-- 'REPLACE_WITH_ARGON2_HASH'. It is not a valid hash, so these accounts cannot
-- sign in until you replace it with a real Argon2id hash (see README.md).
-- No plaintext password appears anywhere in this file.
--
-- Level content (maps, scenes, objectives, hints) mirrors the frontend
-- content in apps/web/src/content so the database can become its source.
-- =============================================================================

BEGIN;

-- -----------------------------------------------------------------------------
-- Roles & permissions
-- -----------------------------------------------------------------------------
INSERT INTO roles (code, name, description, is_system) VALUES
  ('SUPER_ADMIN',    'Super administrator', 'Everything, including role management.', FALSE),
  ('ADMIN',          'Administrator',       'Manages students, curriculum, publication and access.', TRUE),
  ('CONTENT_EDITOR', 'Content editor',      'Edits curriculum, levels, lessons and achievements.', FALSE),
  ('TEACHER',        'Teacher',             'Views progress and unlocks levels for their students.', FALSE),
  ('STUDENT',        'Student',             'Plays missions and writes programs.', TRUE);

INSERT INTO permissions (code, description) VALUES
  ('students.manage',     'Create, disable and reset passwords of students'),
  ('students.view',       'View student accounts'),
  ('progress.view',       'View student progress, attempts and submitted programs'),
  ('levels.unlock',       'Lock / unlock levels for individual students'),
  ('curriculum.manage',   'Create and edit curricula, worlds, levels, objectives, checkpoints, hints, prerequisites'),
  ('levels.publish',      'Publish, unpublish, hide and lock levels'),
  ('content.manage',      'Create and edit lessons'),
  ('achievements.manage', 'Create and edit achievements and rewards'),
  ('statistics.view',     'View platform statistics'),
  ('audit.view',          'Read the audit log'),
  ('roles.manage',        'Manage roles and permissions');

INSERT INTO role_permissions (role_code, permission_code)
SELECT 'SUPER_ADMIN', code FROM permissions;
INSERT INTO role_permissions (role_code, permission_code)
SELECT 'ADMIN', code FROM permissions WHERE code <> 'roles.manage';
INSERT INTO role_permissions (role_code, permission_code) VALUES
  ('CONTENT_EDITOR', 'curriculum.manage'), ('CONTENT_EDITOR', 'content.manage'), ('CONTENT_EDITOR', 'achievements.manage'), ('CONTENT_EDITOR', 'statistics.view'),
  ('TEACHER', 'students.view'), ('TEACHER', 'progress.view'), ('TEACHER', 'levels.unlock'), ('TEACHER', 'statistics.view');

-- -----------------------------------------------------------------------------
-- Accounts (placeholder hashes — replace before use; see README)
-- -----------------------------------------------------------------------------
INSERT INTO users (username, password_hash, display_name, role, must_change_password) VALUES
  ('admin', 'REPLACE_WITH_ARGON2_HASH', 'OneRoboLab Administrator', 'ADMIN', TRUE);

INSERT INTO users (username, password_hash, display_name, role, must_change_password, created_by)
SELECT s.username, 'REPLACE_WITH_ARGON2_HASH', s.display_name, 'STUDENT', TRUE, (SELECT id FROM users WHERE username_normalized = 'admin')
  FROM (VALUES
    ('nguyenvana01', 'Nguyễn Văn A'),
    ('tranthib02',   'Trần Thị B'),
    ('leminhc03',    'Lê Minh C')
  ) AS s(username, display_name);

INSERT INTO student_profiles (user_id, class_label)
SELECT id, 'Robotics Club · Group 1' FROM users WHERE role = 'STUDENT';
INSERT INTO student_settings (student_id, language)
SELECT id, 'vi' FROM users WHERE role = 'STUDENT';
INSERT INTO student_stats (student_id)
SELECT id FROM users WHERE role = 'STUDENT';

