  ('starter-canyon-switchbacks', 'Delivery Plaza', 'LEVEL', 'starter', 'An open canyon plaza where parcel points arrive as coordinates.', '{"lighting":"warmAfternoon"}'::jsonb, 'PUBLISHED'),
  ('starter-gorge-run', 'Gorge Villages', 'LEVEL', 'starter', 'The gorge road with three villages and the storm shelter.', '{"lighting":"warmAfternoon"}'::jsonb, 'PUBLISHED'),
