  ('starter-fallen-trees', 'Foggy Tunnels', 'LEVEL', 'starter', 'The old research tunnels, full of fog and shifting walls.', '{"lighting":"coolDaylight"}'::jsonb, 'PUBLISHED'),
  ('starter-guide-line', 'Recovery Hub', 'LEVEL', 'starter', 'The island hub: bridge site, power depot, a traffic light and the control tower.', '{"lighting":"coolDaylight"}'::jsonb, 'PUBLISHED'),
  ('starter-rescue-arena', 'Rescue City', 'LEVEL', 'starter', 'A whole city district: junction signals, roadworks, survivors to rescue and Rescue HQ.', '{"lighting":"warmAfternoon","chase":{"back":2.3,"height":2.8,"side":0.8}}'::jsonb, 'PUBLISHED'),
