INSERT INTO curricula (name, slug, description, status, sort_order, created_by) VALUES
  ('Robotics Foundations', 'robotics-foundations', 'Sequences, turns, loops and a first sensor: programming a robot step by step.', 'PUBLISHED', 1, (SELECT id FROM users WHERE username_normalized = 'admin')),
  ('Robotics Explorers', 'robotics-explorers', 'Line sensors, variables and multi-step challenges in new worlds.', 'PUBLISHED', 2, (SELECT id FROM users WHERE username_normalized = 'admin'));

