-- Worlds
-- -----------------------------------------------------------------------------
INSERT INTO worlds (curriculum_id, name, slug, short_description, description, theme, accent_color, skills, difficulty, environment_id, map_position, sort_order, status, is_visible) VALUES
  ((SELECT id FROM curricula WHERE slug = 'robotics-foundations'), 'Starter Island', 'starter-island', 'Your first commands', 'A calm test track where your robot takes its first moves. Learn how a program runs step by step, from top to bottom.', 'starter', '#4ade80', ARRAY['Movement', 'Turning', 'Sequences']::text[], 'BEGINNER', 'world-starter-island', '{"x":-6.2,"y":0,"z":3.4}'::jsonb, 1, 'PUBLISHED', TRUE),
  ((SELECT id FROM curricula WHERE slug = 'robotics-foundations'), 'Canyon Circuit', 'canyon-circuit', 'Loops and sensors', 'Winding rock roads and narrow bridges. Repeat patterns with loops and let the distance sensor decide when to stop.', 'canyon', '#fb923c', ARRAY['Loops', 'Distance sensor', 'Conditions']::text[], 'EASY', 'world-canyon-circuit', '{"x":-1.4,"y":0.6,"z":4.4}'::jsonb, 2, 'PUBLISHED', TRUE),
  ((SELECT id FROM curricula WHERE slug = 'robotics-foundations'), 'Frost Valley', 'frost-valley', 'The full rescue run', 'A frozen supply route with checkpoints, cones and barriers. Plan a complete route and deliver the supplies safely.', 'frost', '#7dd3fc', ARRAY['Planning', 'Checkpoints', 'Precision']::text[], 'MEDIUM', 'world-frost-valley', '{"x":3.4,"y":0.2,"z":3}'::jsonb, 3, 'PUBLISHED', TRUE),
  ((SELECT id FROM curricula WHERE slug = 'robotics-explorers'), 'Jungle Ruins', 'jungle-ruins', 'Follow the line', 'Overgrown temple paths hide painted guide lines. Read the line sensors and steer your robot through the ruins.', 'jungle', '#34d399', ARRAY['Line sensors', 'Steering', 'If / else']::text[], 'MEDIUM', 'world-jungle-ruins', '{"x":6,"y":1,"z":-1.8}'::jsonb, 4, 'PUBLISHED', TRUE),
  ((SELECT id FROM curricula WHERE slug = 'robotics-explorers'), 'Sky Lab', 'sky-lab', 'Data and variables', 'A floating research lab full of energy cells and sensors. Count, measure and remember values with variables.', 'skylab', '#a78bfa', ARRAY['Variables', 'Colour sensor', 'Math']::text[], 'HARD', 'world-sky-lab', '{"x":1.4,"y":0.5,"z":-3.4}'::jsonb, 5, 'PUBLISHED', TRUE),
  ((SELECT id FROM curricula WHERE slug = 'robotics-explorers'), 'Lava Core', 'lava-core', 'Master challenges', 'An industrial volcano with moving hazards. Combine everything you know to build robust, efficient programs.', 'lava', '#f87171', ARRAY['Algorithms', 'Optimisation', 'Everything combined']::text[], 'EXPERT', 'world-lava-core', '{"x":-3.8,"y":1.3,"z":-3}'::jsonb, 6, 'PUBLISHED', TRUE);

-- -----------------------------------------------------------------------------
-- Levels (each with its own environment, map and scene)
