INSERT INTO levels (world_id, slug, title, brief_description, description, difficulty, sort_order, status, visibility, access_mode, environment_id,
                    estimated_minutes, xp_reward, max_stars, par_blocks, par_seconds, allowed_blocks, intro_steps, map_definition, scene_config, mission_settings, created_by)
VALUES ((SELECT id FROM worlds WHERE slug = 'starter-island'), 'starter-01', 'First Delivery', 'Your robot has just been switched on. Carry the supply box from Starter Base to the Supply Station and stop on the delivery pad.',
        'Your robot has just been switched on. Carry the supply box from Starter Base to the Supply Station and stop on the delivery pad. Environment: Starter Courtyard — A robotics training campus with a paved practice path and a charging dock.',
        'BEGINNER', 1, 'PUBLISHED', 'VISIBLE', 'AUTO', 'starter-courtyard',
        5, 50, 3, 4, 16, ARRAY['event.start', 'motion.forward', 'motion.backward', 'motion.turnLeft', 'motion.turnRight', 'motion.stop']::text[], ARRAY['Drive down the lane to the loading gate', 'Turn towards the Supply Station', 'Stop on the delivery pad']::text[],
        '{"id":"level-starter-01","name":"Starter Courtyard","schemaVersion":1,"size":{"x":6,"z":4.4},"gridSize":0.5,"floorColor":"white","start":{"x":-2.4,"z":0.9,"heading":0},"finish":{"shape":"rect","center":{"x":-0.8,"z":-0.3},"size":{"x":0.5,"z":0.5},"rotation":0},"entities":[{"id":"cp-1","type":"checkpoint","area":{"shape":"circle","center":{"x":-1.55,"z":0.9},"radius":0.22},"order":1},{"id":"hedge-a1","type":"wall","from":{"x":-2.75,"z":1.32},"to":{"x":-0.38,"z":1.32},"height":0.18,"thickness":0.14},{"id":"hedge-b1","type":"wall","from":{"x":-2.75,"z":0.48},"to":{"x":-1.22,"z":0.48},"height":0.18,"thickness":0.14},{"id":"hedge-a2","type":"wall","from":{"x":-0.38,"z":1.32},"to":{"x":-0.38,"z":-1.25},"height":0.18,"thickness":0.14},{"id":"hedge-b2","type":"wall","from":{"x":-1.22,"z":0.48},"to":{"x":-1.22,"z":-1.25},"height":0.18,"thickness":0.14},{"id":"dock-station","type":"wall","from":{"x":-1.22,"z":-1.25},"to":{"x":-0.38000000000000006,"z":-1.25},"height":0.5,"thickness":0.1}]}'::jsonb,
        '{"path":[{"x":-2.75,"z":0.9},{"x":-0.8,"z":0.9},{"x":-0.8,"z":-1.2}],"pathWidth":0.72}'::jsonb,
        '{"failOnCollision":true,"timeLimit":null,"missionTitle":"First Delivery","missionDescription":"Deliver the supply box and stop inside the delivery zone.","stopInFinish":true,"scoring":{"completionPoints":500,"checkpointPoints":100,"timeBonus":{"parSeconds":16,"maxPoints":200},"efficiencyBonus":{"parBlocks":4,"maxPoints":200},"collisionPenalty":100},"briefing":{"story":"The storm knocked out Starter Island’s robot network. You have just switched on your first robot at Starter Base. The Supply Station across the courtyard needs a box of spare parts before the repairs can begin.","task":"Carry the supply box to the Supply Station and stop on the delivery pad.","objectives":{"primary":"Stop inside the delivery zone without hitting anything","secondary":"Deliver within 16 seconds","optional":"Use 4 blocks or fewer"},"concepts":["Sequence","Move forward","Turn","Stop"],"python":["robot.move_forward(cm)","robot.move_backward(cm)","robot.turn_left(degrees)","robot.turn_right(degrees)","robot.stop()"],"predict":"Before you code: how far is the corner, which way must the robot turn there, and where exactly should it stop?","pseudocode":["drive forward to the loading gate corner","turn left","drive forward onto the pad","stop"],"minutes":5,"tier":"easy","mechanics":["cargo"]}}'::jsonb, (SELECT id FROM users WHERE username_normalized = 'admin'));

INSERT INTO levels (world_id, slug, title, brief_description, description, difficulty, sort_order, status, visibility, access_mode, environment_id,
                    estimated_minutes, xp_reward, max_stars, par_blocks, par_seconds, allowed_blocks, intro_steps, map_definition, scene_config, mission_settings, created_by)
VALUES ((SELECT id FROM worlds WHERE slug = 'starter-island'), 'starter-02', 'Power Station', 'The power yard is dark. Inspect both transformers on the service lanes and park on the charging pad so the station can reboot.',
        'The power yard is dark. Inspect both transformers on the service lanes and park on the charging pad so the station can reboot. Environment: Power Station — The island power yard: hedge-lined service lanes, transformers, pylons and the charging pad.',
        'BEGINNER', 2, 'PUBLISHED', 'VISIBLE', 'AUTO', 'starter-campus-crossing',
        6, 75, 3, 8, 26, ARRAY['event.start', 'motion.forward', 'motion.backward', 'motion.turnLeft', 'motion.turnRight', 'motion.stop']::text[], ARRAY['Plan the whole route first: lane, corner, lane…', 'Pass both transformers', 'Stop on the charging pad']::text[],
        '{"id":"level-starter-02","name":"Power Station","schemaVersion":1,"size":{"x":6,"z":4.4},"gridSize":0.5,"floorColor":"white","start":{"x":-2.4,"z":1.3,"heading":0},"finish":{"shape":"rect","center":{"x":0.4,"z":0.9},"size":{"x":0.5,"z":0.5},"rotation":0},"entities":[{"id":"cp-1","type":"checkpoint","area":{"shape":"circle","center":{"x":-1.2,"z":0.7},"radius":0.22},"order":1},{"id":"cp-2","type":"checkpoint","area":{"shape":"circle","center":{"x":-0.4,"z":0.1},"radius":0.22},"order":2},{"id":"hedge-a1","type":"wall","from":{"x":-2.75,"z":1.72},"to":{"x":-0.78,"z":1.72},"height":0.18,"thickness":0.14},{"id":"hedge-b1","type":"wall","from":{"x":-2.75,"z":0.88},"to":{"x":-1.62,"z":0.88},"height":0.18,"thickness":0.14},{"id":"hedge-a2","type":"wall","from":{"x":-0.78,"z":1.72},"to":{"x":-0.78,"z":0.52},"height":0.18,"thickness":0.14},{"id":"hedge-b2","type":"wall","from":{"x":-1.62,"z":0.88},"to":{"x":-1.62,"z":-0.32},"height":0.18,"thickness":0.14},{"id":"hedge-a3","type":"wall","from":{"x":-0.78,"z":0.52},"to":{"x":-0.02,"z":0.52},"height":0.18,"thickness":0.14},{"id":"hedge-b3","type":"wall","from":{"x":-1.62,"z":-0.32},"to":{"x":0.82,"z":-0.32},"height":0.18,"thickness":0.14},{"id":"hedge-a4","type":"wall","from":{"x":-0.02,"z":0.52},"to":{"x":-0.02,"z":1.85},"height":0.18,"thickness":0.14},{"id":"hedge-b4","type":"wall","from":{"x":0.82,"z":-0.32},"to":{"x":0.82,"z":1.85},"height":0.18,"thickness":0.14},{"id":"dock-station","type":"wall","from":{"x":-0.019999999999999962,"z":1.85},"to":{"x":0.8200000000000001,"z":1.85},"height":0.5,"thickness":0.1}]}'::jsonb,
        '{"path":[{"x":-2.75,"z":1.3},{"x":-1.2,"z":1.3},{"x":-1.2,"z":0.1},{"x":0.4,"z":0.1},{"x":0.4,"z":1.8}],"pathWidth":0.72}'::jsonb,
        '{"failOnCollision":true,"timeLimit":null,"missionTitle":"Power Station","missionDescription":"Inspect both transformers and stop on the charging pad.","stopInFinish":true,"scoring":{"completionPoints":500,"checkpointPoints":100,"timeBonus":{"parSeconds":26,"maxPoints":200},"efficiencyBonus":{"parBlocks":8,"maxPoints":200},"collisionPenalty":100},"briefing":{"story":"With spare parts delivered, the next job is power. Starter Island’s power yard went dark in the storm. The transformers must be inspected and the station needs a robot docked on its charging pad to restart.","task":"Drive the service lanes past both transformers and stop on the charging pad.","objectives":{"primary":"Inspect both transformers and stop on the charging pad without hitting anything","secondary":"Reach the pad within 26 seconds","optional":"Use 8 blocks or fewer"},"concepts":["Route planning","Waypoints","Left and right turns","Sequence"],"python":["robot.move_forward(cm)","robot.turn_left(degrees)","robot.turn_right(degrees)","robot.stop()"],"predict":"Look at the yard from above. How many corners are there, and which ones turn left and which turn right?","pseudocode":["drive to the first corner","turn left","drive past transformer A","turn right","drive past transformer B","turn right","drive onto the charging pad","stop"],"minutes":6,"tier":"easy","mechanics":[]}}'::jsonb, (SELECT id FROM users WHERE username_normalized = 'admin'));

INSERT INTO levels (world_id, slug, title, brief_description, description, difficulty, sort_order, status, visibility, access_mode, environment_id,
