        8, 100, 3, 12, 32, ARRAY['event.start', 'motion.forward', 'motion.backward', 'motion.turnLeft', 'motion.turnRight', 'motion.stop']::text[], ARRAY['Find a gap around the crate pile', 'Watch out for the boulder after it', 'Cross the bridge and stop on the supply pad']::text[],
        '{"id":"level-starter-03","name":"Supply Run","schemaVersion":1,"size":{"x":6,"z":4.4},"gridSize":0.5,"floorColor":"white","start":{"x":-2.6,"z":0.8,"heading":0},"finish":{"shape":"rect","center":{"x":0.1,"z":-1.1},"size":{"x":0.5,"z":0.5},"rotation":0},"entities":[{"id":"cp-1","type":"checkpoint","area":{"shape":"circle","center":{"x":-1.3,"z":0.3},"radius":0.22},"order":1},{"id":"cp-2","type":"checkpoint","area":{"shape":"circle","center":{"x":0.1,"z":-0.35},"radius":0.22},"order":2},{"id":"crate-pile","type":"box","position":{"x":-1.3,"z":0.8},"size":{"x":0.5,"y":0.3,"z":0.5},"rotation":0,"dynamic":false},{"id":"rock-1","type":"obstacle","position":{"x":-0.35,"z":0.3},"radius":0.12,"height":0.2},{"id":"rock-2","type":"obstacle","position":{"x":-2.3,"z":1.3},"radius":0.12,"height":0.18},{"id":"fence-north","type":"wall","from":{"x":-2.95,"z":1.55},"to":{"x":0.52,"z":1.55},"height":0.12,"thickness":0.06},{"id":"fence-west","type":"wall","from":{"x":-2.95,"z":0.05},"to":{"x":-2.95,"z":1.55},"height":0.12,"thickness":0.06},{"id":"fence-east","type":"wall","from":{"x":0.52,"z":1.55},"to":{"x":0.52,"z":-2.05},"height":0.12,"thickness":0.06},{"id":"fence-south","type":"wall","from":{"x":-2.95,"z":0.05},"to":{"x":-0.31999999999999995,"z":0.05},"height":0.12,"thickness":0.06},{"id":"fence-bridge","type":"wall","from":{"x":-0.31999999999999995,"z":0.05},"to":{"x":-0.31999999999999995,"z":-2.05},"height":0.12,"thickness":0.06},{"id":"dock-clinic","type":"wall","from":{"x":-0.31999999999999995,"z":-2.05},"to":{"x":0.52,"z":-2.05},"height":0.5,"thickness":0.1}]}'::jsonb,
        '{"path":[{"x":-2.9000000000000004,"z":0.8},{"x":0.1,"z":0.8},{"x":0.1,"z":-1.9999999999999998}],"pathWidth":0.84,"bridges":[{"from":{"x":0.1,"z":0.05},"to":{"x":0.1,"z":-0.75},"width":0.84,"style":"wood"}],"water":[{"points":[{"x":-3.4,"z":-0.3},{"x":-1.6,"z":-0.42},{"x":0.1,"z":-0.35},{"x":1.4,"z":-0.25},{"x":3.4,"z":-0.4}],"width":0.56,"depth":0.28}]}'::jsonb,
        '{"failOnCollision":true,"timeLimit":null,"missionTitle":"Supply Run","missionDescription":"Go around the debris, cross the bridge and stop on the clinic’s supply pad.","stopInFinish":true,"scoring":{"completionPoints":500,"checkpointPoints":100,"timeBonus":{"parSeconds":32,"maxPoints":200},"efficiencyBonus":{"parBlocks":12,"maxPoints":200},"collisionPenalty":100},"briefing":{"story":"The power is back, but the storm left the meadow trail covered in debris. The riverside clinic across the creek is waiting for its medical supplies — and your robot has no sensors yet. It will only avoid what you plan for.","task":"Plan a route around the debris, cross the creek bridge and stop on the clinic’s supply pad.","objectives":{"primary":"Deliver the supplies to the clinic pad without touching any debris","secondary":"Deliver within 32 seconds","optional":"Use 12 blocks or fewer"},"concepts":["Planned obstacle avoidance","Detours","Route planning","Sequence"],"python":["robot.move_forward(cm)","robot.turn_left(degrees)","robot.turn_right(degrees)","robot.stop()"],"predict":"Which side of the crate pile is free? After the detour, what is still in the way before the bridge?","pseudocode":["drive up to the crate pile","sidestep towards the creek","drive past the pile","sidestep back to the middle","drive to the bridge corner","turn towards the creek","cross the bridge onto the pad","stop"],"minutes":8,"tier":"medium","mechanics":["cargo"]}}'::jsonb, (SELECT id FROM users WHERE username_normalized = 'admin'));

