VALUES ((SELECT id FROM worlds WHERE slug = 'starter-island'), 'starter-04', 'Build the Bridge', 'The stream washed the footbridge away. Push all three bridge blocks into the construction zone, then cross to the far bank.',
        'The stream washed the footbridge away. Push all three bridge blocks into the construction zone, then cross to the far bank. Environment: Bridge Site — A meadow lane beside the washed-out stream, with three bridge blocks and the construction site.',
        'EASY', 4, 'PUBLISHED', 'VISIBLE', 'AUTO', 'starter-meadow-lanes',
        8, 110, 3, 16, 52, ARRAY['event.start', 'motion.forward', 'motion.backward', 'motion.turnLeft', 'motion.turnRight', 'motion.stop', 'motion.speed']::text[], ARRAY['Drive up beside a bridge block', 'Turn towards the construction zone and push it in', 'Back up, do the next block, then drive to the far bank']::text[],
        '{"id":"level-starter-04","name":"Build the Bridge","schemaVersion":1,"size":{"x":6,"z":4.4},"gridSize":0.5,"floorColor":"white","start":{"x":-2.4,"z":0.9,"heading":0},"finish":{"shape":"rect","center":{"x":1.7,"z":0.9},"size":{"x":0.6,"z":0.6},"rotation":0},"entities":[{"id":"site","type":"zone","kind":"construction","area":{"shape":"rect","center":{"x":-0.4,"z":-0.55},"size":{"x":2.6,"z":0.8},"rotation":0},"label":"BRIDGE SITE"},{"id":"block-1","type":"box","position":{"x":-1.2,"z":0.45},"size":{"x":0.12,"y":0.12,"z":0.12},"rotation":0,"dynamic":true},{"id":"block-2","type":"box","position":{"x":-0.4,"z":0.45},"size":{"x":0.12,"y":0.12,"z":0.12},"rotation":0,"dynamic":true},{"id":"block-3","type":"box","position":{"x":0.4,"z":0.45},"size":{"x":0.12,"y":0.12,"z":0.12},"rotation":0,"dynamic":true},{"id":"fence-south","type":"wall","from":{"x":-2.9,"z":1.35},"to":{"x":2.3,"z":1.35},"height":0.12,"thickness":0.06},{"id":"fence-west","type":"wall","from":{"x":-2.9,"z":-1.15},"to":{"x":-2.9,"z":1.35},"height":0.12,"thickness":0.06},{"id":"fence-north","type":"wall","from":{"x":-2.9,"z":-1.15},"to":{"x":2.3,"z":-1.15},"height":0.12,"thickness":0.06},{"id":"fence-east","type":"wall","from":{"x":2.3,"z":-1.15},"to":{"x":2.3,"z":1.35},"height":0.12,"thickness":0.06}]}'::jsonb,
        '{"path":[{"x":-2.7,"z":0.9},{"x":2,"z":0.9}],"pathWidth":0.7,"water":[{"points":[{"x":-3.8,"z":-1.75},{"x":0,"z":-1.6},{"x":3.8,"z":-1.75}],"width":0.7,"depth":0.3}]}'::jsonb,
        '{"failOnCollision":true,"timeLimit":null,"missionTitle":"Build the Bridge","missionDescription":"Push the three bridge blocks into the construction zone and reach the far bank.","scoring":{"completionPoints":500,"checkpointPoints":100,"timeBonus":{"parSeconds":52,"maxPoints":200},"efficiencyBonus":{"parBlocks":16,"maxPoints":200},"collisionPenalty":100},"briefing":{"story":"Power and supplies are flowing again, but the storm washed the footbridge over the meadow stream away. The builders left three bridge blocks beside the lane — your robot has to push them onto the bridge site.","task":"Push all three bridge blocks into the construction zone, then drive to the far bank.","objectives":{"primary":"Push 3 blocks into the construction zone and reach the far bank","secondary":"Finish within 52 seconds","optional":"Use 16 blocks or fewer"},"concepts":["Pushing objects","Repeated steps","Sequence","Backing up"],"python":["robot.move_forward(cm)","robot.move_backward(cm)","robot.turn_left(degrees)","robot.turn_right(degrees)"],"predict":"How far must the robot push so a block ends up inside the zone? Which moves are the same for every block?","pseudocode":["drive beside block 1","turn towards the zone, push, back up, turn back","drive beside block 2 — same moves","drive beside block 3 — same moves","drive to the far bank"],"minutes":8,"tier":"medium","mechanics":["push"]}}'::jsonb, (SELECT id FROM users WHERE username_normalized = 'admin'));

INSERT INTO levels (world_id, slug, title, brief_description, description, difficulty, sort_order, status, visibility, access_mode, environment_id,
