VALUES ((SELECT id FROM worlds WHERE slug = 'starter-island'), 'starter-05', 'Traffic Crossing', 'The traffic lights work again. Cross both zebra crossings on the way to the depot — never on red. Stop at the line and wait for green.',
        'The traffic lights work again. Cross both zebra crossings on the way to the depot — never on red. Stop at the line and wait for green. Environment: Traffic Crossing — Hedge-lined roads with two zebra crossings and their traffic lights on the way to the depot.',
        'EASY', 5, 'PUBLISHED', 'VISIBLE', 'AUTO', 'starter-beacon-field',
        8, 110, 3, 7, 32, ARRAY['event.start', 'motion.forward', 'motion.backward', 'motion.turnLeft', 'motion.turnRight', 'motion.stop', 'motion.speed', 'control.wait']::text[], ARRAY['Watch the lights: when does each one turn green?', 'Stop before the crossing and wait', 'Cross on green — the robot must never enter on red']::text[],
        '{"id":"level-starter-05","name":"Traffic Crossing","schemaVersion":1,"size":{"x":6,"z":4.6},"gridSize":0.5,"floorColor":"white","start":{"x":-2.4,"z":0.8,"heading":0},"finish":{"shape":"rect","center":{"x":0.6,"z":-1.4},"size":{"x":0.6,"z":0.6},"rotation":0},"entities":[{"id":"light-a","type":"trafficLight","position":{"x":-1.2,"z":0.25},"facing":3.141592653589793,"crossing":{"shape":"rect","center":{"x":-1,"z":0.8},"size":{"x":0.3,"z":0.84},"rotation":0},"signal":{"shape":"rect","center":{"x":-1.23,"z":0.8},"size":{"x":0.12,"z":0.3},"rotation":0},"cycle":{"red":8,"green":6,"yellow":1},"offset":0},{"id":"light-b","type":"trafficLight","position":{"x":1.15,"z":0},"facing":-1.5707963267948966,"crossing":{"shape":"rect","center":{"x":0.6,"z":-0.2},"size":{"x":0.84,"z":0.3},"rotation":0},"signal":{"shape":"rect","center":{"x":0.6,"z":0.22},"size":{"x":0.3,"z":0.12},"rotation":0},"cycle":{"red":7,"green":6,"yellow":1},"offset":11},{"id":"hedge-a1","type":"wall","from":{"x":-2.7,"z":1.22},"to":{"x":1.02,"z":1.22},"height":0.12,"thickness":0.06},{"id":"hedge-b1","type":"wall","from":{"x":-2.7,"z":0.38},"to":{"x":0.18,"z":0.38},"height":0.12,"thickness":0.06},{"id":"hedge-a2","type":"wall","from":{"x":1.02,"z":1.22},"to":{"x":1.02,"z":-1.9},"height":0.12,"thickness":0.06},{"id":"hedge-b2","type":"wall","from":{"x":0.18,"z":0.38},"to":{"x":0.18,"z":-1.9},"height":0.12,"thickness":0.06},{"id":"hedge-cap1","type":"wall","from":{"x":1.02,"z":-1.9},"to":{"x":0.18,"z":-1.9},"height":0.12,"thickness":0.06}]}'::jsonb,
        '{"path":[{"x":-2.7,"z":0.8},{"x":0.6,"z":0.8},{"x":0.6,"z":-1.7}],"pathWidth":0.84}'::jsonb,
        '{"failOnCollision":true,"timeLimit":null,"missionTitle":"Traffic Crossing","missionDescription":"Cross both crossings on green and reach the depot.","scoring":{"completionPoints":500,"checkpointPoints":100,"timeBonus":{"parSeconds":32,"maxPoints":200},"efficiencyBonus":{"parBlocks":7,"maxPoints":200},"collisionPenalty":100},"briefing":{"story":"The island’s traffic lights are working again — and the island’s robots have to obey them like everyone else. The depot is on the other side of two zebra crossings.","task":"Drive to the depot without ever entering a crossing on red.","objectives":{"primary":"Reach the depot without crossing on red","secondary":"Finish within 32 seconds","optional":"Use 7 blocks or fewer"},"concepts":["Timing","Wait","Reading a timetable","Sequence"],"python":["robot.move_forward(cm)","robot.turn_left(degrees)","robot.wait(seconds)"],"predict":"The robot drives 25 cm every second. When will it reach the first crossing — and what colour will the light be then?","pseudocode":["drive to the first stop line","wait until light A is green","drive to the corner and turn","drive to the second stop line","wait until light B is green","drive to the depot"],"minutes":8,"tier":"medium","mechanics":["traffic"]}}'::jsonb, (SELECT id FROM users WHERE username_normalized = 'admin'));

