VALUES ((SELECT id FROM worlds WHERE slug = 'starter-island'), 'starter-06', 'Rescue Route', 'Three hikers are stranded in the woods. Reach them strictly in order — 1, 2, 3 — then return to the ranger station. Hiker 2 is on the short way to hiker 1.',
        'Three hikers are stranded in the woods. Reach them strictly in order — 1, 2, 3 — then return to the ranger station. Hiker 2 is on the short way to hiker 1. Environment: Rescue Woods — A boulder-strewn forest clearing where three hikers wait, and the ranger station.',
        'EASY', 6, 'PUBLISHED', 'VISIBLE', 'AUTO', 'starter-boulder-woods',
        8, 120, 3, 11, 40, ARRAY['event.start', 'motion.forward', 'motion.backward', 'motion.turnLeft', 'motion.turnRight', 'motion.stop', 'motion.speed']::text[], ARRAY['Hiker 1 first, then 2, then 3', 'Reaching a hiker out of turn fails the rescue', 'Plan the route round hiker 2']::text[],
        '{"id":"level-starter-06","name":"Rescue Route","schemaVersion":1,"size":{"x":6,"z":4.4},"gridSize":0.5,"floorColor":"white","start":{"x":-2.4,"z":1.2,"heading":0},"finish":{"shape":"rect","center":{"x":1.4,"z":-0.4},"size":{"x":0.6,"z":0.6},"rotation":0},"entities":[{"id":"cp-1","type":"checkpoint","area":{"shape":"circle","center":{"x":-0.6,"z":-0.4},"radius":0.22},"order":1},{"id":"cp-2","type":"checkpoint","area":{"shape":"circle","center":{"x":-0.6,"z":1.2},"radius":0.22},"order":2},{"id":"cp-3","type":"checkpoint","area":{"shape":"circle","center":{"x":1.4,"z":1.2},"radius":0.22},"order":3},{"id":"rock-1","type":"obstacle","position":{"x":0.4,"z":0.4},"radius":0.14,"height":0.18},{"id":"rock-2","type":"obstacle","position":{"x":-1.9,"z":0.3},"radius":0.12,"height":0.16},{"id":"rock-3","type":"obstacle","position":{"x":0.5,"z":-1.3},"radius":0.14,"height":0.18},{"id":"rock-4","type":"obstacle","position":{"x":-2.3,"z":-1.2},"radius":0.12,"height":0.16},{"id":"stump-1","type":"obstacle","position":{"x":-0.1,"z":0.4},"radius":0.08,"height":0.12}]}'::jsonb,
        '{"path":[{"x":-2.7,"z":1.2},{"x":-1.4,"z":1.2},{"x":-1.4,"z":-0.4},{"x":-0.6,"z":-0.4},{"x":-0.6,"z":1.2},{"x":1.4,"z":1.2},{"x":1.4,"z":-0.6}],"pathWidth":0.55}'::jsonb,
        '{"failOnCollision":true,"timeLimit":null,"missionTitle":"Rescue Route","missionDescription":"Reach hikers 1, 2 and 3 in order, then the ranger station.","scoring":{"completionPoints":500,"checkpointPoints":100,"timeBonus":{"parSeconds":40,"maxPoints":200},"efficiencyBonus":{"parBlocks":11,"maxPoints":200},"collisionPenalty":100},"briefing":{"story":"The storm caught three hikers in the woods. The rescue team ranked them by urgency, and your robot has to reach them in exactly that order before returning to the ranger station.","task":"Reach hiker 1, then hiker 2, then hiker 3, then return to the ranger station.","objectives":{"primary":"Rescue the hikers in order 1 → 2 → 3 and return to the station","secondary":"Finish within 40 seconds","optional":"Use 11 blocks or fewer"},"concepts":["Ordered goals","Route planning","Sequence"],"python":["robot.move_forward(cm)","robot.turn_left(degrees)","robot.turn_right(degrees)"],"predict":"Which hiker is on the short way to hiker 1? How can the robot reach hiker 1 without passing hiker 2?","pseudocode":["go north round hiker 2","reach hiker 1","drive south to hiker 2","drive east to hiker 3","drive north to the station"],"minutes":8,"tier":"medium","mechanics":[]},"orderedCheckpoints":true}'::jsonb, (SELECT id FROM users WHERE username_normalized = 'admin'));

INSERT INTO levels (world_id, slug, title, brief_description, description, difficulty, sort_order, status, visibility, access_mode, environment_id,
