VALUES ((SELECT id FROM worlds WHERE slug = 'starter-island'), 'starter-07', 'Broken Bridge', 'A fallen log blocks one of the two river bridges — a different one each run. Check the near bridge with the obstacle sensor and choose your way.',
        'A fallen log blocks one of the two river bridges — a different one each run. Check the near bridge with the obstacle sensor and choose your way. Environment: Broken Bridge — A ring road round the river island with two log bridges, one of them blocked.',
        'MEDIUM', 7, 'PUBLISHED', 'VISIBLE', 'AUTO', 'starter-log-bridge',
        10, 120, 3, 13, 36, ARRAY['event.start', 'motion.forward', 'motion.backward', 'motion.turnLeft', 'motion.turnRight', 'motion.stop', 'motion.speed', 'control.wait', 'control.if', 'control.ifElse', 'sensor.obstacle']::text[], ARRAY['Drive to the near bridge and face it', 'Obstacle ahead? Take the far bridge', 'Otherwise cross right here']::text[],
