        '{"path":[{"x":-2.7,"z":1},{"x":1,"z":1},{"x":1,"z":-1.2},{"x":-1,"z":-1.2},{"x":-1,"z":1}],"pathWidth":0.84,"bridges":[{"from":{"x":-1,"z":0.2},"to":{"x":-1,"z":-0.6},"width":0.84,"style":"log"},{"from":{"x":1,"z":0.2},"to":{"x":1,"z":-0.6},"width":0.84,"style":"log"}],"water":[{"points":[{"x":-3.6,"z":-0.25},{"x":0,"z":-0.15},{"x":3.6,"z":-0.25}],"width":0.5,"depth":0.3}]}'::jsonb,
        '{"failOnCollision":true,"timeLimit":null,"missionTitle":"Broken Bridge","missionDescription":"Find the open bridge and reach the forest camp.","scoring":{"completionPoints":500,"checkpointPoints":100,"timeBonus":{"parSeconds":36,"maxPoints":200},"efficiencyBonus":{"parBlocks":13,"maxPoints":200},"collisionPenalty":100},"briefing":{"story":"The forest camp across the river needs help, but the storm toppled trees onto the log bridges. Each time, a different bridge is blocked — the robot has to check before it chooses.","task":"Look at the near bridge with the obstacle sensor and take whichever bridge is open to the forest camp.","objectives":{"primary":"Reach the forest camp over an open bridge","secondary":"Finish within 36 seconds","optional":"Use 13 blocks or fewer"},"concepts":["if … else","Obstacle sensor","Alternative routes"],"python":["if robot.obstacle_ahead():","else:","robot.move_forward(cm)"],"predict":"Press Reset twice and watch the log. Why can’t a program with only moves work every time?","pseudocode":["drive to the near bridge and face it","if something is ahead:","    take the far bridge to the camp","else:","    cross here to the camp"],"minutes":10,"tier":"medium","mechanics":["variants"]},"variants":[{"id":"near-blocked","add":[{"id":"log-near","type":"wall","from":{"x":-1.3,"z":0.7},"to":{"x":-0.7,"z":0.7},"height":0.12,"thickness":0.1}]},{"id":"far-blocked","add":[{"id":"log-far","type":"wall","from":{"x":0.7,"z":0.7},"to":{"x":1.3,"z":0.7},"height":0.12,"thickness":0.1}]}]}'::jsonb, (SELECT id FROM users WHERE username_normalized = 'admin'));

