                    estimated_minutes, xp_reward, max_stars, par_blocks, par_seconds, allowed_blocks, intro_steps, map_definition, scene_config, mission_settings, created_by)
VALUES ((SELECT id FROM worlds WHERE slug = 'starter-island'), 'starter-08', 'Cargo Station', 'Three crates of tools wait on the cargo shelf. Carry each one to the loading dock — the same steps three times — then park at the charger.',
        'Three crates of tools wait on the cargo shelf. Carry each one to the loading dock — the same steps three times — then park at the charger. Environment: Cargo Station — The cargo hall: a crate shelf, the loading dock and a charging bay.',
        'MEDIUM', 8, 'PUBLISHED', 'VISIBLE', 'AUTO', 'starter-ranger-hut',
        8, 120, 3, 9, 62, ARRAY['event.start', 'motion.forward', 'motion.backward', 'motion.turnLeft', 'motion.turnRight', 'motion.stop', 'motion.speed', 'control.wait', 'control.if', 'control.ifElse', 'sensor.obstacle', 'control.repeat', 'action.pick', 'action.drop']::text[], ARRAY['Pick up the crate in front of the robot', 'Carry it to the dock and drop it', 'Come back — and do it all again with “repeat”']::text[],
        '{"id":"level-starter-08","name":"Cargo Station","schemaVersion":1,"size":{"x":6,"z":4.4},"gridSize":0.5,"floorColor":"white","start":{"x":-1.6,"z":0,"heading":3.141592653589793},"finish":{"shape":"rect","center":{"x":-1.6,"z":-1.2},"size":{"x":0.6,"z":0.6},"rotation":0},"entities":[{"id":"shelf","type":"cargo","position":{"x":-2,"z":0},"items":[{"id":"shelf-1"},{"id":"shelf-2"},{"id":"shelf-3"}]},{"id":"dock","type":"zone","kind":"delivery","area":{"shape":"rect","center":{"x":0.35,"z":0},"size":{"x":0.5,"z":0.5},"rotation":0},"label":"DOCK"},{"id":"wall-south","type":"wall","from":{"x":-2.4,"z":0.5},"to":{"x":0.8,"z":0.5},"height":0.12,"thickness":0.06},{"id":"wall-north","type":"wall","from":{"x":-2.4,"z":-1.65},"to":{"x":0.8,"z":-1.65},"height":0.12,"thickness":0.06},{"id":"wall-west","type":"wall","from":{"x":-2.4,"z":-1.65},"to":{"x":-2.4,"z":0.5},"height":0.12,"thickness":0.06},{"id":"wall-east","type":"wall","from":{"x":0.8,"z":-1.65},"to":{"x":0.8,"z":0.5},"height":0.12,"thickness":0.06}]}'::jsonb,
        '{"path":[{"x":0.6,"z":0},{"x":-1.6,"z":0},{"x":-1.6,"z":-1.4}],"pathWidth":0.7}'::jsonb,
        '{"failOnCollision":true,"timeLimit":null,"missionTitle":"Cargo Station","missionDescription":"Deliver the three crates to the loading dock, then park at the charger.","scoring":{"completionPoints":500,"checkpointPoints":100,"timeBonus":{"parSeconds":62,"maxPoints":200},"efficiencyBonus":{"parBlocks":9,"maxPoints":200},"collisionPenalty":100},"briefing":{"story":"The repair crews need their tools. The cargo station has three crates on its shelf and your robot is the only one fit to carry them to the loading dock.","task":"Deliver all three crates to the loading dock, then park at the charger.","objectives":{"primary":"Deliver 3 crates and park at the charger","secondary":"Finish within 62 seconds","optional":"Use 9 blocks or fewer"},"concepts":["Pick up / drop","repeat","Patterns"],"python":["robot.pick_up()","robot.drop()","for _ in range(3):"],"predict":"Which steps does the robot do for every crate? How many blocks would you need without a repeat block?","pseudocode":["repeat 3 times:","    pick up the crate","    carry it to the dock and drop it","    drive back to the shelf","drive to the charger"],"minutes":8,"tier":"medium","mechanics":["pickup"]}}'::jsonb, (SELECT id FROM users WHERE username_normalized = 'admin'));

