VALUES ((SELECT id FROM worlds WHERE slug = 'starter-island'), 'starter-09', 'Colour Warehouse', 'Red crates go to the red warehouse, blue crates to the blue one — and the order changes every run. Read each crate’s colour before you pick it up.',
        'Red crates go to the red warehouse, blue crates to the blue one — and the order changes every run. Read each crate’s colour before you pick it up. Environment: Colour Warehouse — A sorting hall with a colour-coded crate shelf and the red and blue warehouses.',
        'MEDIUM', 9, 'PUBLISHED', 'VISIBLE', 'AUTO', 'starter-ferry-landing',
        10, 130, 3, 17, 85, ARRAY['event.start', 'motion.forward', 'motion.backward', 'motion.turnLeft', 'motion.turnRight', 'motion.stop', 'motion.speed', 'control.wait', 'control.if', 'control.ifElse', 'sensor.obstacle', 'control.repeat', 'action.pick', 'action.drop', 'sensor.color']::text[], ARRAY['The tile in front of the shelf shows the next crate’s colour', 'Red → east warehouse, blue → south warehouse', 'Four crates, then park']::text[],
        '{"id":"level-starter-09","name":"Colour Warehouse","schemaVersion":1,"size":{"x":6,"z":4.4},"gridSize":0.5,"floorColor":"white","start":{"x":-1.6,"z":0,"heading":3.141592653589793},"finish":{"shape":"rect","center":{"x":-1.6,"z":-1.2},"size":{"x":0.6,"z":0.6},"rotation":0},"entities":[{"id":"shelf","type":"cargo","position":{"x":-2,"z":0},"items":[{"id":"shelf-1","color":"red"},{"id":"shelf-2","color":"blue"},{"id":"shelf-3","color":"blue"},{"id":"shelf-4","color":"red"}],"tile":{"shape":"rect","center":{"x":-1.675,"z":0},"size":{"x":0.12,"z":0.24},"rotation":0}},{"id":"red-store","type":"zone","kind":"delivery","area":{"shape":"rect","center":{"x":0.35,"z":0},"size":{"x":0.5,"z":0.5},"rotation":0},"color":"red","label":"RED"},{"id":"blue-store","type":"zone","kind":"delivery","area":{"shape":"rect","center":{"x":-1.6,"z":1.45},"size":{"x":0.5,"z":0.5},"rotation":0},"color":"blue","label":"BLUE"},{"id":"wall-south","type":"wall","from":{"x":-2.4,"z":1.85},"to":{"x":0.8,"z":1.85},"height":0.12,"thickness":0.06},{"id":"wall-north","type":"wall","from":{"x":-2.4,"z":-1.65},"to":{"x":0.8,"z":-1.65},"height":0.12,"thickness":0.06},{"id":"wall-west","type":"wall","from":{"x":-2.4,"z":-1.65},"to":{"x":-2.4,"z":1.85},"height":0.12,"thickness":0.06},{"id":"wall-east","type":"wall","from":{"x":0.8,"z":-1.65},"to":{"x":0.8,"z":1.85},"height":0.12,"thickness":0.06},{"id":"shelf-inner","type":"wall","from":{"x":-1.1,"z":0.5},"to":{"x":-1.1,"z":1.85},"height":0.12,"thickness":0.06}]}'::jsonb,
        '{"path":[{"x":0.6,"z":0},{"x":-1.6,"z":0},{"x":-1.6,"z":1.6},{"x":-1.6,"z":-1.4}],"pathWidth":0.7}'::jsonb,
        '{"failOnCollision":true,"timeLimit":null,"missionTitle":"Colour Warehouse","missionDescription":"Sort the four crates into the warehouse of their colour, then park.","scoring":{"completionPoints":500,"checkpointPoints":100,"timeBonus":{"parSeconds":85,"maxPoints":200},"efficiencyBonus":{"parBlocks":17,"maxPoints":200},"collisionPenalty":100},"briefing":{"story":"The ferry brought supplies for two warehouses: red crates for the workshop, blue crates for the clinic. They were stacked in a hurry — in a different order every time.","task":"Read each crate’s colour, carry it to the warehouse of that colour, then park.","objectives":{"primary":"Sort all 4 crates into the right warehouses and park","secondary":"Finish within 85 seconds","optional":"Use 17 blocks or fewer"},"concepts":["Colour sensor","if … else","repeat","Sorting"],"python":["robot.color() == \"red\"","robot.pick_up()","robot.drop()"],"predict":"When is the right moment to read the colour — before or after picking up the crate?","pseudocode":["repeat 4 times:","    if the tile is red:","        carry the crate to the red warehouse","    else:","        carry it to the blue warehouse","park at the charger"],"minutes":10,"tier":"medium","mechanics":["pickup","variants"]},"variants":[{"id":"rbbr","remove":["shelf"],"add":[{"id":"shelf","type":"cargo","position":{"x":-2,"z":0},"items":[{"id":"shelf-1","color":"red"},{"id":"shelf-2","color":"blue"},{"id":"shelf-3","color":"blue"},{"id":"shelf-4","color":"red"}],"tile":{"shape":"rect","center":{"x":-1.675,"z":0},"size":{"x":0.12,"z":0.24},"rotation":0}}]},{"id":"brrb","remove":["shelf"],"add":[{"id":"shelf","type":"cargo","position":{"x":-2,"z":0},"items":[{"id":"shelf-1","color":"blue"},{"id":"shelf-2","color":"red"},{"id":"shelf-3","color":"red"},{"id":"shelf-4","color":"blue"}],"tile":{"shape":"rect","center":{"x":-1.675,"z":0},"size":{"x":0.12,"z":0.24},"rotation":0}}]},{"id":"bbrr","remove":["shelf"],"add":[{"id":"shelf","type":"cargo","position":{"x":-2,"z":0},"items":[{"id":"shelf-1","color":"blue"},{"id":"shelf-2","color":"blue"},{"id":"shelf-3","color":"red"},{"id":"shelf-4","color":"red"}],"tile":{"shape":"rect","center":{"x":-1.675,"z":0},"size":{"x":0.12,"z":0.24},"rotation":0}}]}]}'::jsonb, (SELECT id FROM users WHERE username_normalized = 'admin'));

