VALUES ((SELECT id FROM worlds WHERE slug = 'starter-island'), 'starter-10', 'Smart Gate', 'The dock gate opens only for robots that wait at its scanner. The robot starts in a different place every run: measure the distance to the gate.',
        'The dock gate opens only for robots that wait at its scanner. The robot starts in a different place every run: measure the distance to the gate. Environment: Smart Gate — The river dock lane with a smart security gate, its scanner pad and the dock pad.',
        'MEDIUM', 10, 'PUBLISHED', 'VISIBLE', 'AUTO', 'starter-river-docks',
        8, 130, 3, 6, 22, ARRAY['event.start', 'motion.forward', 'motion.backward', 'motion.turnLeft', 'motion.turnRight', 'motion.stop', 'motion.speed', 'control.wait', 'control.if', 'control.ifElse', 'sensor.obstacle', 'control.repeat', 'action.pick', 'action.drop', 'sensor.color', 'sensor.distance', 'logic.compare', 'control.until']::text[], ARRAY['Creep towards the gate until it is less than 30 cm away', 'Wait at the scanner until the gate lifts', 'Drive through and stop on the dock pad']::text[],
        '{"id":"level-starter-10","name":"Smart Gate","schemaVersion":1,"size":{"x":6,"z":4.4},"gridSize":0.5,"floorColor":"white","start":{"x":-2.37,"z":0,"heading":0},"finish":{"shape":"rect","center":{"x":1.6,"z":0},"size":{"x":0.5,"z":0.5},"rotation":0},"entities":[{"id":"gate","type":"gate","from":{"x":0.8,"z":-0.42},"to":{"x":0.8,"z":0.42},"height":0.3,"thickness":0.06,"trigger":{"shape":"rect","center":{"x":0.45,"z":0},"size":{"x":0.4,"z":0.6},"rotation":0},"holdSeconds":1},{"id":"rail-north","type":"wall","from":{"x":-2.9,"z":-0.42},"to":{"x":2.2,"z":-0.42},"height":0.12,"thickness":0.06},{"id":"rail-south","type":"wall","from":{"x":-2.9,"z":0.42},"to":{"x":2.2,"z":0.42},"height":0.12,"thickness":0.06},{"id":"rail-west","type":"wall","from":{"x":-2.9,"z":-0.42},"to":{"x":-2.9,"z":0.42},"height":0.12,"thickness":0.06},{"id":"dock-east","type":"wall","from":{"x":2.2,"z":-0.42},"to":{"x":2.2,"z":0.42},"height":0.5,"thickness":0.1}]}'::jsonb,
        '{"path":[{"x":-2.9,"z":0},{"x":2.1,"z":0}],"pathWidth":0.84,"water":[{"points":[{"x":-3.6,"z":-1.6},{"x":0,"z":-1.5},{"x":3.6,"z":-1.6}],"width":1,"depth":0.34}]}'::jsonb,
        '{"failOnCollision":true,"timeLimit":null,"missionTitle":"Smart Gate","missionDescription":"Wait at the scanner, pass the gate and stop on the dock pad.","stopInFinish":true,"scoring":{"completionPoints":500,"checkpointPoints":100,"timeBonus":{"parSeconds":22,"maxPoints":200},"efficiencyBonus":{"parBlocks":6,"maxPoints":200},"collisionPenalty":100},"briefing":{"story":"The river docks are back in business and their smart gate checks every robot. It only lifts when a robot waits on the scanner pad — and today the robots arrive from all over the yard.","task":"Drive up to the gate, wait at the scanner until it opens, then stop on the dock pad.","objectives":{"primary":"Pass the smart gate and stop on the dock pad","secondary":"Finish within 22 seconds","optional":"Use 6 blocks or fewer"},"concepts":["Distance sensor","Thresholds","repeat until","Feedback"],"python":["robot.distance()","while not robot.distance() < 30:","robot.wait(seconds)"],"predict":"If the robot always drove 260 cm, what would happen when it starts closer to the gate?","pseudocode":["repeat until the gate is closer than 30 cm:","    move forward a little","wait at the scanner","drive onto the dock pad"],"minutes":8,"tier":"medium","mechanics":["gate","variants"]},"variants":[{"id":"far","start":{"x":-2.37,"z":0,"heading":0}},{"id":"middle","start":{"x":-1.92,"z":0,"heading":0}},{"id":"near","start":{"x":-1.48,"z":0,"heading":0}}]}'::jsonb, (SELECT id FROM users WHERE username_normalized = 'admin'));

