VALUES ((SELECT id FROM worlds WHERE slug = 'starter-island'), 'starter-11', 'Traffic Controller', 'Three traffic lights on Signal Avenue, each on its own timetable. Read the signal tile: red → wait, yellow → slow down, green → full speed.',
        'Three traffic lights on Signal Avenue, each on its own timetable. Read the signal tile: red → wait, yellow → slow down, green → full speed. Environment: Signal Avenue — A straight avenue with three traffic lights, each on its own timetable.',
        'HARD', 11, 'PUBLISHED', 'VISIBLE', 'AUTO', 'starter-stepping-stones',
        10, 140, 3, 10, 30, ARRAY['event.start', 'motion.forward', 'motion.backward', 'motion.turnLeft', 'motion.turnRight', 'motion.stop', 'motion.speed', 'control.wait', 'control.if', 'control.ifElse', 'sensor.obstacle', 'control.repeat', 'action.pick', 'action.drop', 'sensor.color', 'sensor.distance', 'logic.compare', 'control.until', 'control.forever']::text[], ARRAY['The tile before each crossing shows its light', 'Red: wait · yellow: slow · green: full speed', 'Drive in small steps inside “repeat forever”']::text[],
        '{"id":"level-starter-11","name":"Signal Avenue","schemaVersion":1,"size":{"x":6.4,"z":4.4},"gridSize":0.5,"floorColor":"white","start":{"x":-2.6,"z":0,"heading":0},"finish":{"shape":"rect","center":{"x":2.55,"z":0},"size":{"x":0.6,"z":0.6},"rotation":0},"entities":[{"id":"light-1","type":"trafficLight","position":{"x":-1.55,"z":-0.6},"facing":3.141592653589793,"crossing":{"shape":"rect","center":{"x":-1.3,"z":0},"size":{"x":0.3,"z":0.84},"rotation":0},"signal":{"shape":"rect","center":{"x":-1.545,"z":0},"size":{"x":0.15,"z":0.3},"rotation":0},"cycle":{"red":5,"green":5,"yellow":2},"offset":0},{"id":"light-2","type":"trafficLight","position":{"x":-0.15,"z":-0.6},"facing":3.141592653589793,"crossing":{"shape":"rect","center":{"x":0.1,"z":0},"size":{"x":0.3,"z":0.84},"rotation":0},"signal":{"shape":"rect","center":{"x":-0.145,"z":0},"size":{"x":0.15,"z":0.3},"rotation":0},"cycle":{"red":4,"green":5,"yellow":2},"offset":3},{"id":"light-3","type":"trafficLight","position":{"x":1.25,"z":-0.6},"facing":3.141592653589793,"crossing":{"shape":"rect","center":{"x":1.5,"z":0},"size":{"x":0.3,"z":0.84},"rotation":0},"signal":{"shape":"rect","center":{"x":1.255,"z":0},"size":{"x":0.15,"z":0.3},"rotation":0},"cycle":{"red":6,"green":5,"yellow":2},"offset":7},{"id":"rail-north","type":"wall","from":{"x":-2.95,"z":-0.42},"to":{"x":2.95,"z":-0.42},"height":0.12,"thickness":0.06},{"id":"rail-south","type":"wall","from":{"x":-2.95,"z":0.42},"to":{"x":2.95,"z":0.42},"height":0.12,"thickness":0.06},{"id":"rail-west","type":"wall","from":{"x":-2.95,"z":-0.42},"to":{"x":-2.95,"z":0.42},"height":0.12,"thickness":0.06},{"id":"rail-east","type":"wall","from":{"x":2.95,"z":-0.42},"to":{"x":2.95,"z":0.42},"height":0.12,"thickness":0.06}]}'::jsonb,
        '{"path":[{"x":-2.95,"z":0},{"x":2.9,"z":0}],"pathWidth":0.84}'::jsonb,
        '{"failOnCollision":true,"timeLimit":null,"missionTitle":"Traffic Controller","missionDescription":"Obey all three lights and reach the end of Signal Avenue.","scoring":{"completionPoints":500,"checkpointPoints":100,"timeBonus":{"parSeconds":30,"maxPoints":200},"efficiencyBonus":{"parBlocks":10,"maxPoints":200},"collisionPenalty":100},"briefing":{"story":"Signal Avenue is the island’s busiest street and its three traffic lights run on different timetables. Your robot will be the first autonomous delivery van to drive it.","task":"Drive the whole avenue reacting to each light: wait on red, slow down on yellow, full speed on green.","objectives":{"primary":"Reach the end of the avenue without crossing on red","secondary":"Finish within 30 seconds","optional":"Use 10 blocks or fewer"},"concepts":["if / else if / else","Speed control","Signal states","repeat forever"],"python":["if robot.color() == \"red\":","elif robot.color() == \"yellow\":","else:","robot.set_speed(percent)"],"predict":"What should the robot do on yellow? Why is it safer to react to the light than to count seconds?","pseudocode":["repeat forever:","    if the signal is red: wait","    else if it is yellow: slow down, small step","    else: full speed, small step"],"minutes":10,"tier":"hard","mechanics":["traffic"]}}'::jsonb, (SELECT id FROM users WHERE username_normalized = 'admin'));

INSERT INTO levels (world_id, slug, title, brief_description, description, difficulty, sort_order, status, visibility, access_mode, environment_id,
