VALUES ((SELECT id FROM worlds WHERE slug = 'starter-island'), 'starter-12', 'Line Rescue', 'A fisher is stranded at the end of the harbour. Follow the painted rescue line along the quay — nine bends, both ways. Write a line follower.',
        'A fisher is stranded at the end of the harbour. Follow the painted rescue line along the quay — nine bends, both ways. Write a line follower. Environment: Line Rescue — Quays of the storm-hit harbour with a painted rescue line to the stranded fisher.',
        'HARD', 12, 'PUBLISHED', 'VISIBLE', 'AUTO', 'starter-harbour-spiral',
        10, 140, 3, 7, 100, ARRAY['event.start', 'motion.forward', 'motion.backward', 'motion.turnLeft', 'motion.turnRight', 'motion.stop', 'motion.speed', 'control.wait', 'control.if', 'control.ifElse', 'sensor.obstacle', 'control.repeat', 'action.pick', 'action.drop', 'sensor.color', 'sensor.distance', 'logic.compare', 'control.until', 'control.forever', 'sensor.line', 'logic.not', 'logic.and', 'logic.or']::text[], ARRAY['Keep the line sensor on the edge of the line', 'On the line: steer right. Off the line: steer left', 'Small steps, repeated forever']::text[],
        '{"id":"level-starter-12","name":"Line Rescue","schemaVersion":1,"size":{"x":7.6,"z":4.6},"gridSize":0.5,"floorColor":"white","start":{"x":-2.8,"z":0.9,"heading":0},"finish":{"shape":"rect","center":{"x":0.2,"z":-1.3},"size":{"x":0.6,"z":0.6},"rotation":0},"entities":[{"id":"cp-1","type":"checkpoint","area":{"shape":"circle","center":{"x":0.3,"z":0.55},"radius":0.22},"order":1},{"id":"cp-2","type":"checkpoint","area":{"shape":"circle","center":{"x":2.2,"z":-0.15},"radius":0.22},"order":2},{"id":"line-guide","type":"line","points":[{"x":-2.8,"z":0.9},{"x":-1.8,"z":0.9},{"x":-1.1,"z":0.2},{"x":0,"z":0.2},{"x":0.6,"z":0.9},{"x":1.6,"z":0.9},{"x":2.2,"z":0.3},{"x":2.2,"z":-0.6},{"x":1.4,"z":-1.3},{"x":0.2,"z":-1.3}],"width":0.05,"closed":false},{"id":"fence-a1","type":"wall","from":{"x":-3.1,"z":1.52},"to":{"x":-1.543188,"z":1.52},"height":0.12,"thickness":0.06},{"id":"fence-b1","type":"wall","from":{"x":-3.1,"z":0.28},"to":{"x":-2.056812,"z":0.28},"height":0.12,"thickness":0.06},{"id":"fence-a2","type":"wall","from":{"x":-1.543188,"z":1.52},"to":{"x":-0.843188,"z":0.82},"height":0.12,"thickness":0.06},{"id":"fence-b2","type":"wall","from":{"x":-2.056812,"z":0.28},"to":{"x":-1.356812,"z":-0.42},"height":0.12,"thickness":0.06},{"id":"fence-a3","type":"wall","from":{"x":-0.843188,"z":0.82},"to":{"x":-0.28516,"z":0.82},"height":0.12,"thickness":0.06},{"id":"fence-b3","type":"wall","from":{"x":-1.356812,"z":-0.42},"to":{"x":0.28516,"z":-0.42},"height":0.12,"thickness":0.06},{"id":"fence-a4","type":"wall","from":{"x":-0.28516,"z":0.82},"to":{"x":0.31484,"z":1.52},"height":0.12,"thickness":0.06},{"id":"fence-b4","type":"wall","from":{"x":0.28516,"z":-0.42},"to":{"x":0.88516,"z":0.28},"height":0.12,"thickness":0.06},{"id":"fence-a5","type":"wall","from":{"x":0.31484,"z":1.52},"to":{"x":1.856812,"z":1.52},"height":0.12,"thickness":0.06},{"id":"fence-b5","type":"wall","from":{"x":0.88516,"z":0.28},"to":{"x":1.343188,"z":0.28},"height":0.12,"thickness":0.06},{"id":"fence-a6","type":"wall","from":{"x":1.856812,"z":1.52},"to":{"x":2.82,"z":0.556812},"height":0.12,"thickness":0.06},{"id":"fence-b6","type":"wall","from":{"x":1.343188,"z":0.28},"to":{"x":1.58,"z":0.043188},"height":0.12,"thickness":0.06},{"id":"fence-a7","type":"wall","from":{"x":2.82,"z":0.556812},"to":{"x":2.82,"z":-0.881336},"height":0.12,"thickness":0.06},{"id":"fence-b7","type":"wall","from":{"x":1.58,"z":0.043188},"to":{"x":1.58,"z":-0.318664},"height":0.12,"thickness":0.06},{"id":"fence-a8","type":"wall","from":{"x":2.82,"z":-0.881336},"to":{"x":1.632956,"z":-1.92},"height":0.12,"thickness":0.06},{"id":"fence-b8","type":"wall","from":{"x":1.58,"z":-0.318664},"to":{"x":1.167044,"z":-0.68},"height":0.12,"thickness":0.06},{"id":"fence-a9","type":"wall","from":{"x":1.632956,"z":-1.92},"to":{"x":-0.3,"z":-1.92},"height":0.12,"thickness":0.06},{"id":"fence-b9","type":"wall","from":{"x":1.167044,"z":-0.68},"to":{"x":-0.3,"z":-0.68},"height":0.12,"thickness":0.06},{"id":"fence-cap1","type":"wall","from":{"x":-0.3,"z":-1.92},"to":{"x":-0.3,"z":-0.68},"height":0.12,"thickness":0.06}]}'::jsonb,
        '{"path":[{"x":-2.8,"z":0.9},{"x":-1.8,"z":0.9},{"x":-1.1,"z":0.2},{"x":0,"z":0.2},{"x":0.6,"z":0.9},{"x":1.6,"z":0.9},{"x":2.2,"z":0.3},{"x":2.2,"z":-0.6},{"x":1.4,"z":-1.3},{"x":0.2,"z":-1.3}],"pathWidth":0.7,"water":[{"points":[{"x":-3.8,"z":2.3},{"x":0,"z":2.15},{"x":3.8,"z":2.3}],"width":0.9,"depth":0.3}]}'::jsonb,
        '{"failOnCollision":true,"timeLimit":null,"missionTitle":"Line Rescue","missionDescription":"Follow the rescue line to the stranded fisher.","scoring":{"completionPoints":500,"checkpointPoints":100,"timeBonus":{"parSeconds":100,"maxPoints":200},"efficiencyBonus":{"parBlocks":7,"maxPoints":200},"collisionPenalty":100},"briefing":{"story":"The storm surge cut off the end of the harbour, and a fisher is waiting there. The island painted rescue lines on the quays so robots can find their way without a map.","task":"Follow the rescue line all the way to the stranded fisher.","objectives":{"primary":"Reach the fisher along the rescue line","secondary":"Finish within 100 seconds","optional":"Use 7 blocks or fewer"},"concepts":["Line sensor","Feedback loop","repeat forever","if … else"],"python":["while True:","if robot.on_line():","robot.turn_right(degrees)"],"predict":"The line has nine bends. Why does a program with only two small moves still follow every one of them?","pseudocode":["repeat forever:","    if the sensor sees the line: turn a little right, step","    else: turn a little left, step"],"minutes":10,"tier":"hard","mechanics":[]}}'::jsonb, (SELECT id FROM users WHERE username_normalized = 'admin'));

INSERT INTO levels (world_id, slug, title, brief_description, description, difficulty, sort_order, status, visibility, access_mode, environment_id,
