VALUES ((SELECT id FROM worlds WHERE slug = 'starter-island'), 'starter-13', 'Sensor Challenge', 'Gate 2: follow the line, drive round fallen crates, then read the exit signal — red: right, blue: left. The layout changes every reset.',
        'Gate 2: follow the line, drive round fallen crates, then read the exit signal — red: right, blue: left. The layout changes every reset. Environment: Sensor Gate — Gate 2’s test course: a guide line, fallen crates and two signalled exits.',
        'HARD', 13, 'PUBLISHED', 'VISIBLE', 'AUTO', 'starter-boat-dock',
        14, 160, 3, 26, 80, ARRAY['event.start', 'motion.forward', 'motion.backward', 'motion.turnLeft', 'motion.turnRight', 'motion.stop', 'motion.speed', 'control.wait', 'control.if', 'control.ifElse', 'sensor.obstacle', 'control.repeat', 'action.pick', 'action.drop', 'sensor.color', 'sensor.distance', 'logic.compare', 'control.until', 'control.forever', 'sensor.line', 'logic.not', 'logic.and', 'logic.or']::text[], ARRAY['Follow the line', 'Crate ahead? Drive round it', 'Red signal: exit right · blue signal: exit left']::text[],
        '{"id":"level-starter-13","name":"Sensor Challenge","schemaVersion":1,"size":{"x":8.2,"z":3.4},"gridSize":0.5,"floorColor":"white","start":{"x":-2.8,"z":0.4,"heading":0},"finish":{"shape":"rect","center":{"x":2.3,"z":0.4},"size":{"x":0.6,"z":0.6},"rotation":0},"entities":[{"id":"cp-1","type":"checkpoint","area":{"shape":"circle","center":{"x":-0.2,"z":0},"radius":0.22},"order":1},{"id":"line-guide","type":"line","points":[{"x":-2.8,"z":0.4},{"x":-0.6,"z":0.4},{"x":0.2,"z":-0.4},{"x":2.6,"z":-0.4}],"width":0.05,"closed":false},{"id":"fence-a1","type":"wall","from":{"x":-3.1,"z":1.45},"to":{"x":-0.165076,"z":1.45},"height":0.12,"thickness":0.06},{"id":"fence-b1","type":"wall","from":{"x":-3.1,"z":-0.65},"to":{"x":-1.034924,"z":-0.65},"height":0.12,"thickness":0.06},{"id":"fence-a2","type":"wall","from":{"x":-0.165076,"z":1.45},"to":{"x":0.634924,"z":0.65},"height":0.12,"thickness":0.06},{"id":"fence-b2","type":"wall","from":{"x":-1.034924,"z":-0.65},"to":{"x":-0.234924,"z":-1.45},"height":0.12,"thickness":0.06},{"id":"fence-a3","type":"wall","from":{"x":0.634924,"z":0.65},"to":{"x":3.1,"z":0.65},"height":0.12,"thickness":0.06},{"id":"fence-b3","type":"wall","from":{"x":-0.234924,"z":-1.45},"to":{"x":3.1,"z":-1.45},"height":0.12,"thickness":0.06},{"id":"fence-cap1","type":"wall","from":{"x":3.1,"z":0.65},"to":{"x":3.1,"z":-1.45},"height":0.12,"thickness":0.06}]}'::jsonb,
        '{"path":[{"x":-2.8,"z":0.4},{"x":-0.6,"z":0.4},{"x":0.2,"z":-0.4},{"x":2.6,"z":-0.4},{"x":2.6,"z":-0.4}],"pathWidth":0.9,"water":[{"points":[{"x":-3.8,"z":2.4},{"x":0,"z":2.2},{"x":3.8,"z":2.4}],"width":1.1,"depth":0.34}]}'::jsonb,
        '{"failOnCollision":true,"timeLimit":null,"missionTitle":"Sensor Challenge","missionDescription":"Follow the line round the crates and take the exit the signal shows.","scoring":{"completionPoints":500,"checkpointPoints":100,"timeBonus":{"parSeconds":80,"maxPoints":200},"efficiencyBonus":{"parBlocks":26,"maxPoints":200},"collisionPenalty":100},"briefing":{"story":"Gate 2 guards the road to the robot facility. Its test course is rebuilt after every attempt: crates in new places, a different exit open. Only a robot that senses the world gets through.","task":"Follow the guide line, drive round any crate on it and leave through the exit the signal shows.","objectives":{"primary":"Leave through the open exit without touching a crate or the closed exit","secondary":"Finish within 80 seconds","optional":"Use 26 blocks or fewer"},"concepts":["Combining sensors","else if priorities","Line following","Randomised layouts"],"python":["if robot.obstacle_ahead():","elif robot.color() == \"red\":","elif robot.on_line():"],"predict":"If the line check came first, would the robot ever notice the crate or the exit signal? Why does the order of the checks matter?","pseudocode":["repeat forever:","    if a crate is ahead: detour","    else if the signal is red: exit right","    else if the signal is blue: exit left","    else: follow the line"],"minutes":14,"tier":"boss","mechanics":["variants","hazard"]},"variants":[{"id":"a","add":[{"id":"crate-1","type":"box","position":{"x":-1.6,"z":0.4},"size":{"x":0.2,"y":0.22,"z":0.44},"rotation":0,"dynamic":false},{"id":"crate-2","type":"box","position":{"x":1.3,"z":-0.4},"size":{"x":0.2,"y":0.22,"z":0.44},"rotation":0,"dynamic":false},{"id":"exit-signal","type":"colorZone","area":{"shape":"rect","center":{"x":2.35,"z":-0.4},"size":{"x":0.2,"z":0.5},"rotation":0},"color":"red"},{"id":"wrong-exit","type":"zone","kind":"hazard","area":{"shape":"rect","center":{"x":2.4,"z":-1.2000000000000002},"size":{"x":0.4,"z":0.4},"rotation":0},"label":"CLOSED"}],"finish":{"shape":"rect","center":{"x":2.3,"z":0.4},"size":{"x":0.6,"z":0.6},"rotation":0}},{"id":"b","add":[{"id":"crate-1","type":"box","position":{"x":-1.9,"z":0.4},"size":{"x":0.2,"y":0.22,"z":0.44},"rotation":0,"dynamic":false},{"id":"crate-2","type":"box","position":{"x":1.3,"z":-0.4},"size":{"x":0.2,"y":0.22,"z":0.44},"rotation":0,"dynamic":false},{"id":"exit-signal","type":"colorZone","area":{"shape":"rect","center":{"x":2.35,"z":-0.4},"size":{"x":0.2,"z":0.5},"rotation":0},"color":"blue"},{"id":"wrong-exit","type":"zone","kind":"hazard","area":{"shape":"rect","center":{"x":2.4,"z":0.4},"size":{"x":0.4,"z":0.4},"rotation":0},"label":"CLOSED"}],"finish":{"shape":"rect","center":{"x":2.3,"z":-1.2000000000000002},"size":{"x":0.6,"z":0.6},"rotation":0}},{"id":"c","add":[{"id":"crate-1","type":"box","position":{"x":-1.3,"z":0.4},"size":{"x":0.2,"y":0.22,"z":0.44},"rotation":0,"dynamic":false},{"id":"crate-2","type":"box","position":{"x":1.35,"z":-0.4},"size":{"x":0.2,"y":0.22,"z":0.44},"rotation":0,"dynamic":false},{"id":"exit-signal","type":"colorZone","area":{"shape":"rect","center":{"x":2.35,"z":-0.4},"size":{"x":0.2,"z":0.5},"rotation":0},"color":"blue"},{"id":"wrong-exit","type":"zone","kind":"hazard","area":{"shape":"rect","center":{"x":2.4,"z":0.4},"size":{"x":0.4,"z":0.4},"rotation":0},"label":"CLOSED"}],"finish":{"shape":"rect","center":{"x":2.3,"z":-1.2000000000000002},"size":{"x":0.6,"z":0.6},"rotation":0}},{"id":"d","add":[{"id":"crate-1","type":"box","position":{"x":-2,"z":0.4},"size":{"x":0.2,"y":0.22,"z":0.44},"rotation":0,"dynamic":false},{"id":"exit-signal","type":"colorZone","area":{"shape":"rect","center":{"x":2.35,"z":-0.4},"size":{"x":0.2,"z":0.5},"rotation":0},"color":"red"},{"id":"wrong-exit","type":"zone","kind":"hazard","area":{"shape":"rect","center":{"x":2.4,"z":-1.2000000000000002},"size":{"x":0.4,"z":0.4},"rotation":0},"label":"CLOSED"}],"finish":{"shape":"rect","center":{"x":2.3,"z":0.4},"size":{"x":0.6,"z":0.6},"rotation":0}}]}'::jsonb, (SELECT id FROM users WHERE username_normalized = 'admin'));

