VALUES ((SELECT id FROM worlds WHERE slug = 'starter-island'), 'starter-14', 'Flooded Village', 'The high street is flooded or blocked by fallen trees — in different places every run. Spot water and trees in time and go round them.',
        'The high street is flooded or blocked by fallen trees — in different places every run. Spot water and trees in time and go round them. Environment: Flooded Village — A village high street with flood water, fallen trees and the village square.',
        'HARD', 14, 'PUBLISHED', 'VISIBLE', 'AUTO', 'starter-sensor-lab',
        12, 160, 3, 14, 70, ARRAY['event.start', 'motion.forward', 'motion.backward', 'motion.turnLeft', 'motion.turnRight', 'motion.stop', 'motion.speed', 'control.wait', 'control.if', 'control.ifElse', 'sensor.obstacle', 'control.repeat', 'action.pick', 'action.drop', 'sensor.color', 'sensor.distance', 'logic.compare', 'control.until', 'control.forever', 'sensor.line', 'logic.not', 'logic.and', 'logic.or']::text[], ARRAY['Blue floor = flood water: never drive in', 'A tree ahead shows on the obstacle sensor', 'Back up and go round through the village square']::text[],
        '{"id":"level-starter-14","name":"Flooded Village","schemaVersion":1,"size":{"x":6.2,"z":4.4},"gridSize":0.5,"floorColor":"white","start":{"x":-2.6,"z":0.9,"heading":0},"finish":{"shape":"rect","center":{"x":2.3,"z":0.9},"size":{"x":0.6,"z":0.6},"rotation":0},"entities":[{"id":"fence-south","type":"wall","from":{"x":-2.95,"z":1.32},"to":{"x":2.9,"z":1.32},"height":0.12,"thickness":0.06},{"id":"fence-north","type":"wall","from":{"x":-2.95,"z":-0.9},"to":{"x":2.9,"z":-0.9},"height":0.12,"thickness":0.06},{"id":"fence-west","type":"wall","from":{"x":-2.95,"z":-0.9},"to":{"x":-2.95,"z":1.32},"height":0.12,"thickness":0.06},{"id":"fence-east","type":"wall","from":{"x":2.9,"z":-0.9},"to":{"x":2.9,"z":1.32},"height":0.12,"thickness":0.06},{"id":"block-house-0","type":"box","position":{"x":-1.6,"z":-0.45},"size":{"x":0.5,"y":0.4,"z":0.4},"rotation":0,"dynamic":false},{"id":"block-house-1","type":"box","position":{"x":-0.2,"z":-0.45},"size":{"x":0.5,"y":0.4,"z":0.4},"rotation":0,"dynamic":false},{"id":"block-house-2","type":"box","position":{"x":1.2,"z":-0.45},"size":{"x":0.5,"y":0.4,"z":0.4},"rotation":0,"dynamic":false}]}'::jsonb,
        '{"path":[{"x":-2.9,"z":0.9},{"x":2.8,"z":0.9}],"pathWidth":0.84}'::jsonb,
        '{"failOnCollision":true,"timeLimit":null,"missionTitle":"Flooded Village","missionDescription":"Avoid the floods and fallen trees and reach the shelter.","scoring":{"completionPoints":500,"checkpointPoints":100,"timeBonus":{"parSeconds":70,"maxPoints":200},"efficiencyBonus":{"parBlocks":14,"maxPoints":200},"collisionPenalty":100},"briefing":{"story":"The river burst its banks in the night. Parts of the village high street are under water and trees have fallen across others — and the water keeps moving. The shelter at the end of the street needs supplies.","task":"Drive down the high street to the shelter, going round every flood and fallen tree.","objectives":{"primary":"Reach the shelter without driving into water or hitting a tree","secondary":"Finish within 70 seconds","optional":"Use 14 blocks or fewer"},"concepts":["Hazard zones","or","Combining sensors","Detours"],"python":["if robot.color() == \"blue\" or robot.obstacle_ahead():","robot.move_backward(cm)"],"predict":"The colour sensor sits 7.5 cm in front of the wheels. Why does that leave just enough time to stop before the water?","pseudocode":["repeat forever:","    if the floor is blue or something is ahead:","        back up and drive round through the square","    move forward a little"],"minutes":12,"tier":"hard","mechanics":["hazard","variants"]},"variants":[{"id":"a","add":[{"id":"flood-0","type":"zone","kind":"hazard","area":{"shape":"rect","center":{"x":-1.6,"z":0.9},"size":{"x":0.5,"z":0.84},"rotation":0},"color":"blue","label":"FLOOD"},{"id":"log-tree-1","type":"wall","from":{"x":-0.2,"z":0.68},"to":{"x":-0.2,"z":1.2},"height":0.16,"thickness":0.15},{"id":"flood-2","type":"zone","kind":"hazard","area":{"shape":"rect","center":{"x":1.2,"z":0.9},"size":{"x":0.5,"z":0.84},"rotation":0},"color":"blue","label":"FLOOD"}]},{"id":"b","add":[{"id":"log-tree-0","type":"wall","from":{"x":-1.6,"z":0.68},"to":{"x":-1.6,"z":1.2},"height":0.16,"thickness":0.15},{"id":"flood-1","type":"zone","kind":"hazard","area":{"shape":"rect","center":{"x":-0.2,"z":0.9},"size":{"x":0.5,"z":0.84},"rotation":0},"color":"blue","label":"FLOOD"}]},{"id":"c","add":[{"id":"flood-1","type":"zone","kind":"hazard","area":{"shape":"rect","center":{"x":-0.2,"z":0.9},"size":{"x":0.5,"z":0.84},"rotation":0},"color":"blue","label":"FLOOD"},{"id":"log-tree-2","type":"wall","from":{"x":1.2,"z":0.68},"to":{"x":1.2,"z":1.2},"height":0.16,"thickness":0.15}]},{"id":"d","add":[{"id":"flood-0","type":"zone","kind":"hazard","area":{"shape":"rect","center":{"x":-1.6,"z":0.9},"size":{"x":0.5,"z":0.84},"rotation":0},"color":"blue","label":"FLOOD"},{"id":"flood-1","type":"zone","kind":"hazard","area":{"shape":"rect","center":{"x":-0.2,"z":0.9},"size":{"x":0.5,"z":0.84},"rotation":0},"color":"blue","label":"FLOOD"},{"id":"flood-2","type":"zone","kind":"hazard","area":{"shape":"rect","center":{"x":1.2,"z":0.9},"size":{"x":0.5,"z":0.84},"rotation":0},"color":"blue","label":"FLOOD"}]}]}'::jsonb, (SELECT id FROM users WHERE username_normalized = 'admin'));

