VALUES ((SELECT id FROM worlds WHERE slug = 'starter-island'), 'starter-15', 'Bridge Engineer', 'One plank of the long bridge is damaged — a different one every run. Compute where it is from mission.segments, wait there for the crane, then reach the tower.',
        'One plank of the long bridge is damaged — a different one every run. Compute where it is from mission.segments, wait there for the crane, then reach the tower. Environment: Bridge Engineer — A long steel bridge over a ravine with a repair crane gate and the tower.',
        'HARD', 15, 'PUBLISHED', 'VISIBLE', 'AUTO', 'starter-facility-yard',
        12, 170, 3, 10, 26, ARRAY['event.start', 'motion.forward', 'motion.backward', 'motion.turnLeft', 'motion.turnRight', 'motion.stop', 'motion.speed', 'control.wait', 'control.if', 'control.ifElse', 'sensor.obstacle', 'control.repeat', 'action.pick', 'action.drop', 'sensor.color', 'sensor.distance', 'logic.compare', 'control.until', 'control.forever', 'sensor.line', 'logic.not', 'logic.and', 'logic.or', 'control.while', 'variable.set', 'variable.change', 'variable.get', 'math.add', 'math.subtract', 'math.multiply', 'math.divide', 'mission.value']::text[], ARRAY['mission.segments says how many 40 cm segments after the bridge head (60 cm away)', 'Stop there and wait for the crane', 'Then drive the rest of the 420 cm to the tower']::text[],
        '{"id":"level-starter-15","name":"Bridge Engineer","schemaVersion":1,"size":{"x":6,"z":4.4},"gridSize":0.5,"floorColor":"white","start":{"x":-2.6,"z":0,"heading":0},"finish":{"shape":"rect","center":{"x":1.6,"z":0},"size":{"x":0.4,"z":0.5},"rotation":0},"entities":[{"id":"cp-1","type":"checkpoint","area":{"shape":"circle","center":{"x":-0.7999999999999998,"z":0},"radius":0.15},"order":1},{"id":"gate","type":"gate","from":{"x":1,"z":-0.42},"to":{"x":1,"z":0.42},"height":0.3,"thickness":0.06,"trigger":{"shape":"rect","center":{"x":-0.7999999999999998,"z":0},"size":{"x":0.3,"z":0.6},"rotation":0},"holdSeconds":1.5},{"id":"rail-north","type":"wall","from":{"x":-2.95,"z":-0.42},"to":{"x":2,"z":-0.42},"height":0.12,"thickness":0.06},{"id":"rail-south","type":"wall","from":{"x":-2.95,"z":0.42},"to":{"x":2,"z":0.42},"height":0.12,"thickness":0.06},{"id":"rail-west","type":"wall","from":{"x":-2.95,"z":-0.42},"to":{"x":-2.95,"z":0.42},"height":0.12,"thickness":0.06},{"id":"dock-tower","type":"wall","from":{"x":2,"z":-0.42},"to":{"x":2,"z":0.42},"height":0.5,"thickness":0.1}]}'::jsonb,
        '{"path":[{"x":-2.95,"z":0},{"x":1.95,"z":0}],"pathWidth":0.84,"bridges":[{"from":{"x":-1.6,"z":0},"to":{"x":1.1,"z":0},"width":0.84,"style":"steel"}],"water":[{"points":[{"x":-0.25,"z":-2.6},{"x":-0.25,"z":2.6}],"width":2.2,"depth":0.6}]}'::jsonb,
        '{"failOnCollision":true,"timeLimit":null,"missionTitle":"Bridge Engineer","missionDescription":"Stop at the damaged plank until the crane is done, then stop on the tower pad.","stopInFinish":true,"scoring":{"completionPoints":500,"checkpointPoints":100,"timeBonus":{"parSeconds":26,"maxPoints":200},"efficiencyBonus":{"parBlocks":10,"maxPoints":200},"collisionPenalty":100},"briefing":{"story":"The long steel bridge to the robot facility survived the storm — almost. Every night the inspectors find a different damaged plank, and the control room radios its position to the repair robot.","task":"Compute where the damaged plank is, wait there until the crane has repaired it, then stop on the tower pad.","objectives":{"primary":"Wait at the damaged plank, then stop on the tower pad","secondary":"Finish within 26 seconds","optional":"Use 10 blocks or fewer"},"concepts":["Variables","Arithmetic","Mission data","Blocks ⇄ Python"],"python":["d = mission.segments * 40 + 60","robot.move_forward(d)","robot.move_forward(420 - d)"],"predict":"If mission.segments is 5, how far is the plank? And how far is it from there to the tower (420 cm from the start)?","pseudocode":["d = segments × 40 + 60","drive d","wait for the crane","drive 420 − d"],"minutes":12,"tier":"hard","mechanics":["data","variants","gate"]},"data":{"segments":3},"variants":[{"id":"segments-3","remove":["cp-1","gate"],"add":[{"id":"cp-1","type":"checkpoint","area":{"shape":"circle","center":{"x":-0.7999999999999998,"z":0},"radius":0.15},"order":1},{"id":"gate","type":"gate","from":{"x":1,"z":-0.42},"to":{"x":1,"z":0.42},"height":0.3,"thickness":0.06,"trigger":{"shape":"rect","center":{"x":-0.7999999999999998,"z":0},"size":{"x":0.3,"z":0.6},"rotation":0},"holdSeconds":1.5}],"data":{"segments":3}},{"id":"segments-4","remove":["cp-1","gate"],"add":[{"id":"cp-1","type":"checkpoint","area":{"shape":"circle","center":{"x":-0.3999999999999999,"z":0},"radius":0.15},"order":1},{"id":"gate","type":"gate","from":{"x":1,"z":-0.42},"to":{"x":1,"z":0.42},"height":0.3,"thickness":0.06,"trigger":{"shape":"rect","center":{"x":-0.3999999999999999,"z":0},"size":{"x":0.3,"z":0.6},"rotation":0},"holdSeconds":1.5}],"data":{"segments":4}},{"id":"segments-5","remove":["cp-1","gate"],"add":[{"id":"cp-1","type":"checkpoint","area":{"shape":"circle","center":{"x":0,"z":0},"radius":0.15},"order":1},{"id":"gate","type":"gate","from":{"x":1,"z":-0.42},"to":{"x":1,"z":0.42},"height":0.3,"thickness":0.06,"trigger":{"shape":"rect","center":{"x":0,"z":0},"size":{"x":0.3,"z":0.6},"rotation":0},"holdSeconds":1.5}],"data":{"segments":5}},{"id":"segments-6","remove":["cp-1","gate"],"add":[{"id":"cp-1","type":"checkpoint","area":{"shape":"circle","center":{"x":0.40000000000000036,"z":0},"radius":0.15},"order":1},{"id":"gate","type":"gate","from":{"x":1,"z":-0.42},"to":{"x":1,"z":0.42},"height":0.3,"thickness":0.06,"trigger":{"shape":"rect","center":{"x":0.40000000000000036,"z":0},"size":{"x":0.3,"z":0.6},"rotation":0},"holdSeconds":1.5}],"data":{"segments":6}}],"editor":"split"}'::jsonb, (SELECT id FROM users WHERE username_normalized = 'admin'));

