VALUES ((SELECT id FROM worlds WHERE slug = 'starter-island'), 'starter-16', 'Emergency Dispatcher', 'Dispatch radios which of four rescue stations needs the medical kit (mission.target). Deliver it into that bay and return to the dispatch pad.',
        'Dispatch radios which of four rescue stations needs the medical kit (mission.target). Deliver it into that bay and return to the dispatch pad. Environment: Dispatch Street — A street of four rescue stations and the dispatch pad.',
        'HARD', 16, 'PUBLISHED', 'VISIBLE', 'AUTO', 'starter-signal-crossing',
