        '{"path":[{"x":0.6,"z":0},{"x":-1.6,"z":0},{"x":-1.6,"z":1.6},{"x":-1.6,"z":-1.4}],"pathWidth":0.7}'::jsonb,
        '{"failOnCollision":true,"timeLimit":null,"missionTitle":"Robot Factory","missionDescription":"Deliver all ten parts to the right lines, then park.","scoring":{"completionPoints":500,"checkpointPoints":100,"timeBonus":{"parSeconds":95,"maxPoints":200},"efficiencyBonus":{"parBlocks":22,"maxPoints":200},"collisionPenalty":100},"briefing":{"story":"The outpost factory is building new rescue robots. Its feeder is full of parts — motor parts in red, sensor parts in blue — and the assembly lines are waiting.","task":"Deliver all ten parts to the line of their colour, then park at the charger.","objectives":{"primary":"Sort all 10 parts and park","secondary":"Finish within 95 seconds","optional":"Use 22 blocks or fewer"},"concepts":["Functions","def","for × 10","Reusing code"],"python":["def to_motors():","to_motors()","for _ in range(10):"],"predict":"How many blocks would ten deliveries take without functions? How many with them?","pseudocode":["def to_motors(): deliver east and come back","def to_sensors(): deliver south and come back","repeat 10 times:","    if the tile is red: to_motors()","    else: to_sensors()","park"],"minutes":14,"tier":"hard","mechanics":["functions","pickup","variants"]},"variants":[{"id":"shift-1","remove":["feeder"],"add":[{"id":"feeder","type":"cargo","position":{"x":-2,"z":0},"items":[{"id":"feeder-1","color":"red"},{"id":"feeder-2","color":"blue"},{"id":"feeder-3","color":"blue"},{"id":"feeder-4","color":"red"},{"id":"feeder-5","color":"red"},{"id":"feeder-6","color":"blue"},{"id":"feeder-7","color":"red"},{"id":"feeder-8","color":"blue"},{"id":"feeder-9","color":"blue"},{"id":"feeder-10","color":"red"}],"tile":{"shape":"rect","center":{"x":-1.675,"z":0},"size":{"x":0.12,"z":0.24},"rotation":0}}]},{"id":"shift-2","remove":["feeder"],"add":[{"id":"feeder","type":"cargo","position":{"x":-2,"z":0},"items":[{"id":"feeder-1","color":"blue"},{"id":"feeder-2","color":"blue"},{"id":"feeder-3","color":"red"},{"id":"feeder-4","color":"blue"}