        '{"failOnCollision":true,"timeLimit":null,"missionTitle":"Island Recovery","missionDescription":"Finish every repair and reach the control tower.","scoring":{"bonusPoints":150,"completionPoints":500,"checkpointPoints":100,"timeBonus":{"parSeconds":75,"maxPoints":200},"efficiencyBonus":{"parBlocks":22,"maxPoints":200},"collisionPenalty":100},"briefing":{"story":"One day before the Arena: the island council wants every system back at once — the bridge, the power depot and the traffic lights — before the control tower can declare the island recovered.","task":"Push the bridge block onto the site, deliver both generator parts, obey the traffic light and reach the control tower.","objectives":{"primary":"Finish all repairs and reach the control tower","secondary":"Finish within 75 seconds (bonus)","optional":"Visit the energy core (bonus)"},"concepts":["Combining systems","Planning","go to x, y","Bonus objectives"],"python":["robot.go_to(x, y)","while robot.color() != \"green\":","robot.pick_up()"],"predict":"Which part of the job would you do first, and why? Is there a route that also passes the energy core without wasting time?","pseudocode":["push the block onto the site","repeat 2: fetch a part, carry it to the depot","go to the stop line","wait until the light is green","drive to the control tower"],"minutes":18,"tier":"boss","mechanics":["push","pickup","traffic","hazard","coordinates"]},"editor":"python"}'::jsonb, (SELECT id FROM users WHERE username_normalized = 'admin'));

