        '{"failOnCollision":true,"timeLimit":180,"missionTitle":"Smart Island Rescue","missionDescription":"Carry a survivor to the hospital before time runs out.","scoring":{"bonusPoints":150,"completionPoints":500,"checkpointPoints":100,"timeBonus":{"parSeconds":60,"maxPoints":200},"efficiencyBonus":{"parBlocks":24,"maxPoints":200},"collisionPenalty":100},"briefing":{"story":"The island is repaired — now the Arena tests whether its robots can work on their own. Rescue City at rush hour: carts on every crossing, a survivor waiting, the hospital up the street and the clock running.","task":"Get past the patrol carts safely, pick up the survivor and drop them at the hospital before time runs out.","objectives":{"primary":"Deliver a survivor to the hospital within 180 s, without a crash","secondary":"Bonus: finish within 60 s","optional":"Bonus: rescue both survivors"},"concepts":["Dynamic obstacles","Autonomous behaviour","Time pressure","Everything together"],"python":["while robot.distance() > 50:","robot.wait(0.1)","robot.pick_up()","while robot.color() != \"green\":"],"predict":"A cart crosses the avenue every 8 seconds. When is the safest moment to cross its track — and how can the robot know that moment has come?","pseudocode":["for each cart track:","    stop before it","    wait until the cart passes in front","    wait until it has gone","    cross at full speed","pick up the survivor","Hospital Street: wait for green","drive to the hospital, drop"],"minutes":20,"tier":"boss","mechanics":["movers","pickup","traffic","variants"]},"variants":[{"id":"rush-a","remove":["cart-1","cart-2"],"add":[{"id":"cart-1","type":"mover","from":{"x":-1,"z":0.7},"to":{"x":-1,"z":2.4},"radius":0.1,"height":0.22,"period":8,"offset":6.92},{"id":"cart-2","type":"mover","from":{"x":0.6,"z":0.7},"to":{"x":0.6,"z":2.4},"radius":0.1,"height":0.22,"period":9,"offset":4.985}]},{"id":"rush-b","remove":["cart-1","cart-2"],"add":[{"id":"cart-1","type":"mover","from":{"x":-1,"z":0.7},"to":{"x":-1,"z":2.4},"radius":0.1,"height":0.22,"period":7,"offset":5.655},{"id":"cart-2","type":"mover","from":{"x":0.6,"z":0.7},"to":{"x":0.6,"z":2.4},"radius":0.1,"height":0.22,"period":8,"offset":3.72}]},{"id":"rush-c","remove":["cart-1","cart-2"],"add":[{"id":"cart-1","type":"mover","from":{"x":-1,"z":0.7},"to":{"x":-1,"z":2.4},"radius":0.1,"height":0.22,"period":9,"offset":8.185},{"id":"cart-2","type":"mover","from":{"x":0.6,"z":0.7},"to":{"x":0.6,"z":2.4},"radius":0.1,"height":0.22,"period":7,"offset":2.455}]}],"editor":"python"}'::jsonb, (SELECT id FROM users WHERE username_normalized = 'admin'));

