INSERT INTO level_hints (level_id, title, content, cost, sort_order) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-02'), 'Hint 1', 'Use the top camera to see the whole yard. Write the route down before you code it: which way is each corner — left or right?', 0, 1),
  ((SELECT id FROM levels WHERE slug = 'starter-02'), 'Hint 2', 'drive to the first corner → turn left → drive past transformer A → turn right → drive past transformer B → turn right → drive onto the pad → stop.', 0, 2),
  ((SELECT id FROM levels WHERE slug = 'starter-02'), 'Hint 3', 'move forward 120 → turn left 90 → move forward 120 → turn right 90 → move forward ? → turn right 90 → move forward ? → stop. The lanes are made of 40 cm slabs.', 0, 3),
  ((SELECT id FROM levels WHERE slug = 'starter-02'), 'Hint 4', 'move forward 120 → turn left 90 → move forward 120 → turn right 90 → move forward 160 → turn right 90 → move forward 80 → stop.', 10, 4);

INSERT INTO level_checkpoints (level_id, code, name, sort_order, position, radius) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-03'), 'cp-1', 'Get past the crate pile', 1, '{"x":-1.3,"y":0,"z":0.3}'::jsonb, 0.22),
  ((SELECT id FROM levels WHERE slug = 'starter-03'), 'cp-2', 'Cross the creek bridge', 2, '{"x":0.1,"y":0,"z":-0.35}'::jsonb, 0.22);
INSERT INTO level_objectives (level_id, code, title, objective_type, checkpoint_id, config, sort_order, required) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-03'), 'cp-1', 'Get past the crate pile', 'REACH_CHECKPOINT', (SELECT id FROM level_checkpoints WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-03') AND code = 'cp-1'), '{}'::jsonb, 1, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-03'), 'cp-2', 'Cross the creek bridge', 'REACH_CHECKPOINT', (SELECT id FROM level_checkpoints WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-03') AND code = 'cp-2'), '{}'::jsonb, 2, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-03'), 'goal', 'Stop on the clinic’s supply pad', 'REACH_GOAL', NULL, '{}'::jsonb, 3, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-03'), 'safe', 'Don’t hit any obstacles', 'AVOID_COLLISIONS', NULL, '{"maxCollisions":0}'::jsonb, 4, TRUE);
INSERT INTO level_hints (level_id, title, content, cost, sort_order) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-03'), 'Hint 1', 'There are no sensors yet, so the robot can’t see the debris — you have to plan the path. Look from the top camera: the gap is on the creek side of the crate pile.', 0, 1),
  ((SELECT id FROM levels WHERE slug = 'starter-03'), 'Hint 2', 'drive towards the pile → turn left → sidestep → turn right → drive past the pile → turn right → back to the middle of the lane → turn left → drive to the bridge → turn left → cross and stop on the pad.', 0, 2),
  ((SELECT id FROM levels WHERE slug = 'starter-03'), 'Hint 3', 'move forward 80 → turn left 90 → move forward 50 → turn right 90 → move forward 100 → turn right 90 → move forward 50 → turn left 90 → move forward ? → turn left 90 → move forward ? → stop.', 0, 3),
  ((SELECT id FROM levels WHERE slug = 'starter-03'), 'Hint 4', 'move forward 80 → turn left 90 → move forward 50 → turn right 90 → move forward 100 → turn right 90 → move forward 50 → turn left 90 → move forward 90 → turn left 90 → move forward 190 → stop.', 10, 4);

INSERT INTO level_objectives (level_id, code, title, objective_type, checkpoint_id, config, sort_order, required) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-04'), 'build', 'Push 3 blocks into the construction zone', 'CUSTOM', NULL, '{"tracked":true,"kind":"pushToZone","zoneId":"site","count":3}'::jsonb, 1, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-04'), 'goal', 'Reach the far bank', 'REACH_GOAL', NULL, '{}'::jsonb, 2, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-04'), 'safe', 'Don’t hit any obstacles', 'AVOID_COLLISIONS', NULL, '{"maxCollisions":0}'::jsonb, 3, TRUE);
INSERT INTO level_hints (level_id, title, content, cost, sort_order) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-04'), 'Hint 1', 'The robot can push a block simply by driving into it. Every block needs the same moves: drive beside it, turn, push, back up, turn back.', 0, 1),
  ((SELECT id FROM levels WHERE slug = 'starter-04'), 'Hint 2', 'drive to block 1 → turn left → push forward → drive backward → turn right → drive to block 2 → … → drive to the far bank.', 0, 2),
  ((SELECT id FROM levels WHERE slug = 'starter-04'), 'Hint 3', 'move forward 120 → turn left 90 → move forward 120 → move backward 120 → turn right 90 → move forward ? → … The blocks are 80 cm apart.', 0, 3),
  ((SELECT id FROM levels WHERE slug = 'starter-04'), 'Hint 4', 'move forward 120 → turn left 90 → move forward 120 → move backward 120 → turn right 90 → move forward 80 → turn left 90 → move forward 120 → move backward 120 → turn right 90 → move forward 80 → turn left 90 → move forward 120 → move backward 120 → turn right 90 → move forward 130.', 10, 4);

INSERT INTO level_objectives (level_id, code, title, objective_type, checkpoint_id, config, sort_order, required) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-05'), 'goal', 'Reach the depot', 'REACH_GOAL', NULL, '{}'::jsonb, 1, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-05'), 'safe', 'Don’t hit any obstacles', 'AVOID_COLLISIONS', NULL, '{"maxCollisions":0}'::jsonb, 2, TRUE);
INSERT INTO level_hints (level_id, title, content, cost, sort_order) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-05'), 'Hint 1', 'Press Run once and watch the timer: light A turns green at 8 s, light B is red from 17 s to 24 s. A “wait” block pauses the robot.', 0, 1),
  ((SELECT id FROM levels WHERE slug = 'starter-05'), 'Hint 2', 'drive to the line of crossing A → wait until it is green → drive to the corner → turn left → drive to the line of crossing B → wait → drive to the depot.', 0, 2),
  ((SELECT id FROM levels WHERE slug = 'starter-05'), 'Hint 3', 'move forward 110 → wait ? → move forward 190 → turn left 90 → move forward 50 → wait ? → move forward 170. The robot needs about 4.4 s to reach the first line.', 0, 3),
  ((SELECT id FROM levels WHERE slug = 'starter-05'), 'Hint 4', 'move forward 110 → wait 4 → move forward 190 → turn left 90 → move forward 50 → wait 6 → move forward 170.', 10, 4);

