INSERT INTO level_objectives (level_id, code, title, objective_type, checkpoint_id, config, sort_order, required) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-06'), 'cp-1', 'Rescue hiker 1', 'REACH_CHECKPOINT', (SELECT id FROM level_checkpoints WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-06') AND code = 'cp-1'), '{}'::jsonb, 1, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-06'), 'cp-2', 'Rescue hiker 2', 'REACH_CHECKPOINT', (SELECT id FROM level_checkpoints WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-06') AND code = 'cp-2'), '{}'::jsonb, 2, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-06'), 'cp-3', 'Rescue hiker 3', 'REACH_CHECKPOINT', (SELECT id FROM level_checkpoints WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-06') AND code = 'cp-3'), '{}'::jsonb, 3, TRUE),
