INSERT INTO level_hints (level_id, title, content, cost, sort_order) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-06'), 'Hint 1', 'Use the top camera. Driving straight east reaches hiker 2 first — that is the wrong order. Go round: north first.', 0, 1),
  ((SELECT id FROM levels WHERE slug = 'starter-06'), 'Hint 2', 'drive a little east → turn left → drive north → turn right → reach hiker 1 → turn right → drive south to hiker 2 → turn left → drive east to hiker 3 → turn left → drive to the station.', 0, 2),
  ((SELECT id FROM levels WHERE slug = 'starter-06'), 'Hint 3', 'move forward 100 → turn left 90 → move forward 160 → turn right 90 → move forward 80 → turn right 90 → move forward ? → turn left 90 → move forward ? → turn left 90 → move forward 160.', 0, 3),
  ((SELECT id FROM levels WHERE slug = 'starter-06'), 'Hint 4', 'move forward 100 → turn left 90 → move forward 160 → turn right 90 → move forward 80 → turn right 90 → move forward 160 → turn left 90 → move forward 200 → turn left 90 → move forward 160.', 10, 4);

INSERT INTO level_objectives (level_id, code, title, objective_type, checkpoint_id, config, sort_order, required) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-07'), 'goal', 'Reach the forest camp', 'REACH_GOAL', NULL, '{}'::jsonb, 1, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-07'), 'safe', 'Don’t hit any obstacles', 'AVOID_COLLISIONS', NULL, '{"maxCollisions":0}'::jsonb, 2, TRUE);
INSERT INTO level_hints (level_id, title, content, cost, sort_order) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-07'), 'Hint 1', 'Press Reset a few times: the log moves. One program has to work both ways — the robot must look before it chooses.', 0, 1),
  ((SELECT id FROM levels WHERE slug = 'starter-07'), 'Hint 2', 'drive to the near bridge → turn towards it → if obstacle ahead → (go to the far bridge, cross, drive to the camp) else → (cross here, drive to the camp).', 0, 2),
  ((SELECT id FROM levels WHERE slug = 'starter-07'), 'Hint 3', 'move forward 140 → turn left 90 → if obstacle ahead? then → turn right 90 → move forward 200 → turn left 90 → move forward ? → turn left 90 → move forward 100 else → move forward ? → turn right 90 → move forward 100.', 0, 3),
  ((SELECT id FROM levels WHERE slug = 'starter-07'), 'Hint 4', 'move forward 140 → turn left 90 → if obstacle ahead? then → turn right 90 → move forward 200 → turn left 90 → move forward 220 → turn left 90 → move forward 100 else → move forward 220 → turn right 90 → move forward 100.', 10, 4);

INSERT INTO level_objectives (level_id, code, title, objective_type, checkpoint_id, config, sort_order, required) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-08'), 'deliver', 'Deliver 3 crates to the dock', 'CUSTOM', NULL, '{"tracked":true,"kind":"deliverCargo","count":3}'::jsonb, 1, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-08'), 'goal', 'Park at the charger', 'REACH_GOAL', NULL, '{}'::jsonb, 2, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-08'), 'safe', 'Don’t hit any obstacles', 'AVOID_COLLISIONS', NULL, '{"maxCollisions":0}'::jsonb, 3, TRUE);
INSERT INTO level_hints (level_id, title, content, cost, sort_order) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-08'), 'Hint 1', 'One delivery is six steps. Three deliveries are the same six steps three times — put them inside a “repeat” block.', 0, 1),
  ((SELECT id FROM levels WHERE slug = 'starter-08'), 'Hint 2', 'repeat 3 { pick up → turn round → drive to the dock → drop → turn round → drive back } → turn to the charger → drive to it.', 0, 2),
  ((SELECT id FROM levels WHERE slug = 'starter-08'), 'Hint 3', 'repeat 3 { pick up crate → turn right 180 → move forward ? → drop crate → turn left 180 → move forward ? } → turn right 90 → move forward 120.', 0, 3),
  ((SELECT id FROM levels WHERE slug = 'starter-08'), 'Hint 4', 'repeat 3 { pick up crate → turn right 180 → move forward 170 → drop crate → turn left 180 → move forward 170 } → turn right 90 → move forward 120.', 10, 4);

INSERT INTO level_objectives (level_id, code, title, objective_type, checkpoint_id, config, sort_order, required) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-09'), 'deliver', 'Sort 4 crates by colour', 'CUSTOM', NULL, '{"tracked":true,"kind":"deliverCargo","count":4}'::jsonb, 1, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-09'), 'goal', 'Park at the charger', 'REACH_GOAL', NULL, '{}'::jsonb, 2, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-09'), 'safe', 'Don’t hit any obstacles', 'AVOID_COLLISIONS', NULL, '{"maxCollisions":0}'::jsonb, 3, TRUE);
INSERT INTO level_hints (level_id, title, content, cost, sort_order) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-09'), 'Hint 1', 'Read the tile before picking: the colour sensor sits just in front of the robot, right over the tile.', 0, 1),
  ((SELECT id FROM levels WHERE slug = 'starter-09'), 'Hint 2', 'repeat 4 { if colour is red → (pick up, carry east, drop, come back) else → (pick up, carry south, drop, come back) } → park.', 0, 2),
  ((SELECT id FROM levels WHERE slug = 'starter-09'), 'Hint 3', 'repeat 4 { if colour is red? then → pick up → turn right 180 → move forward 170 → drop → turn left 180 → move forward 170 else → pick up → turn left 90 → move forward ? → drop → move backward ? → turn right 90 } → turn right 90 → move forward 120.', 0, 3),
  ((SELECT id FROM levels WHERE slug = 'starter-09'), 'Hint 4', 'repeat 4 { if colour is red? then → pick up → turn right 180 → move forward 170 → drop → turn left 180 → move forward 170 else → pick up → turn left 90 → move forward 120 → drop → move backward 120 → turn right 90 } → turn right 90 → move forward 120.', 10, 4);

INSERT INTO level_objectives (level_id, code, title, objective_type, checkpoint_id, config, sort_order, required) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-10'), 'goal', 'Stop on the dock pad', 'REACH_GOAL', NULL, '{}'::jsonb, 1, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-10'), 'safe', 'Don’t hit any obstacles', 'AVOID_COLLISIONS', NULL, '{"maxCollisions":0}'::jsonb, 2, TRUE);
INSERT INTO level_hints (level_id, title, content, cost, sort_order) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-10'), 'Hint 1', 'Press Reset: the robot starts somewhere else each time. “distance” tells you how far the gate is — drive in small steps until it is close.', 0, 1),
  ((SELECT id FROM levels WHERE slug = 'starter-10'), 'Hint 2', 'repeat until distance < 30 { move forward a little } → wait for the gate → drive onto the pad.', 0, 2),
  ((SELECT id FROM levels WHERE slug = 'starter-10'), 'Hint 3', 'repeat until distance (cm) < 30 { move forward 5 } → wait 2 → move forward ?', 0, 3),
  ((SELECT id FROM levels WHERE slug = 'starter-10'), 'Hint 4', 'repeat until distance (cm) < 30 { move forward 5 } → wait 2 → move forward 125.', 10, 4);

INSERT INTO level_objectives (level_id, code, title, objective_type, checkpoint_id, config, sort_order, required) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-11'), 'goal', 'Reach the end of the avenue', 'REACH_GOAL', NULL, '{}'::jsonb, 1, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-11'), 'safe', 'Don’t hit any obstacles', 'AVOID_COLLISIONS', NULL, '{"maxCollisions":0}'::jsonb, 2, TRUE);
INSERT INTO level_hints (level_id, title, content, cost, sort_order) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-11'), 'Hint 1', 'Don’t time the lights — react to them. The colour sensor reads the signal tile just before each crossing.', 0, 1),
  ((SELECT id FROM levels WHERE slug = 'starter-11'), 'Hint 2', 'repeat forever { if red → wait a moment, else if yellow → slow speed and a small step, else → full speed and a small step }.', 0, 2),
  ((SELECT id FROM levels WHERE slug = 'starter-11'), 'Hint 3', 'repeat forever { if colour is red? then → wait 0.1 else → if colour is yellow? then → set speed to ? → move forward 5 else → set speed to ? → move forward 5 }.', 0, 3),
  ((SELECT id FROM levels WHERE slug = 'starter-11'), 'Hint 4', 'repeat forever { if colour is red? then → wait 0.1 else → if colour is yellow? then → set speed to 30 → move forward 5 else → set speed to 100 → move forward 5 }.', 10, 4);

