  ((SELECT id FROM levels WHERE slug = 'starter-12'), 'cp-2', 'Pass the crane', 'REACH_CHECKPOINT', (SELECT id FROM level_checkpoints WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-12') AND code = 'cp-2'), '{}'::jsonb, 2, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-12'), 'goal', 'Reach the fisher', 'REACH_GOAL', NULL, '{}'::jsonb, 3, TRUE),
