INSERT INTO level_hints (level_id, title, content, cost, sort_order) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-12'), 'Hint 1', 'A line follower wiggles along one edge of the line: it never needs to know where the bends are.', 0, 1),
  ((SELECT id FROM levels WHERE slug = 'starter-12'), 'Hint 2', 'repeat forever { if line detected → turn a little right and step; else → turn a little left and step }.', 0, 2),
  ((SELECT id FROM levels WHERE slug = 'starter-12'), 'Hint 3', 'repeat forever { if line detected? then → turn right ? → move forward 3 else → turn left ? → move forward 3 }.', 0, 3),
  ((SELECT id FROM levels WHERE slug = 'starter-12'), 'Hint 4', 'repeat forever { if line detected? then → turn right 15 → move forward 3 else → turn left 15 → move forward 3 }.', 10, 4);

INSERT INTO level_checkpoints (level_id, code, name, sort_order, position, radius) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-13'), 'cp-1', 'Pass the dogleg', 1, '{"x":-0.2,"y":0,"z":0}'::jsonb, 0.22);
INSERT INTO level_objectives (level_id, code, title, objective_type, checkpoint_id, config, sort_order, required) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-13'), 'cp-1', 'Pass the dogleg', 'REACH_CHECKPOINT', (SELECT id FROM level_checkpoints WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-13') AND code = 'cp-1'), '{}'::jsonb, 1, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-13'), 'goal', 'Leave by the open exit', 'REACH_GOAL', NULL, '{}'::jsonb, 2, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-13'), 'safe', 'Don’t hit any obstacles', 'AVOID_COLLISIONS', NULL, '{"maxCollisions":0}'::jsonb, 3, TRUE);
INSERT INTO level_hints (level_id, title, content, cost, sort_order) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-13'), 'Hint 1', 'Order matters: check the crate first, then the exit signal, and only follow the line when nothing else is going on.', 0, 1),
  ((SELECT id FROM levels WHERE slug = 'starter-13'), 'Hint 2', 'repeat forever { if obstacle → detour; else if red → turn right and drive out; else if blue → turn left and drive out; else follow the line }.', 0, 2),
  ((SELECT id FROM levels WHERE slug = 'starter-13'), 'Hint 3', 'Detour = left 90 → forward 60 → right 90 → forward 100 → right 90 → forward 60 → left 90. Exit = turn 90 → forward 80.', 0, 3),
  ((SELECT id FROM levels WHERE slug = 'starter-13'), 'Hint 4', 'repeat forever { if obstacle ahead? → { detour } else → { if colour is red? → { turn right 90 → move forward 80 } else → { if colour is blue? → { turn left 90 → move forward 80 } else → { if line detected? → turn right 15 → move forward 3 else → turn left 15 → move forward 3 } } } }.', 10, 4);

INSERT INTO level_objectives (level_id, code, title, objective_type, checkpoint_id, config, sort_order, required) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-14'), 'goal', 'Reach the shelter', 'REACH_GOAL', NULL, '{}'::jsonb, 1, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-14'), 'safe', 'Don’t hit any obstacles', 'AVOID_COLLISIONS', NULL, '{"maxCollisions":0}'::jsonb, 2, TRUE);
INSERT INTO level_hints (level_id, title, content, cost, sort_order) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-14'), 'Hint 1', 'The colour sensor is a little in front of the wheels: it sees the water before the robot drives in. Both dangers need the same detour.', 0, 1),
  ((SELECT id FROM levels WHERE slug = 'starter-14'), 'Hint 2', 'repeat forever { if (colour is blue) or (obstacle ahead) → back up and drive round; move forward a little }.', 0, 2),
  ((SELECT id FROM levels WHERE slug = 'starter-14'), 'Hint 3', 'Detour = move backward 20 → turn left 90 → forward 50 → turn right 90 → forward 100 → turn right 90 → forward 50 → turn left 90.', 0, 3),
  ((SELECT id FROM levels WHERE slug = 'starter-14'), 'Hint 4', 'repeat forever { if colour is blue? or obstacle ahead? → { move backward 20 → turn left 90 → move forward 50 → turn right 90 → move forward 100 → turn right 90 → move forward 50 → turn left 90 }; move forward 5 }.', 10, 4);

INSERT INTO level_checkpoints (level_id, code, name, sort_order, position, radius) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-15'), 'cp-1', 'Reach the damaged plank', 1, '{"x":-0.7999999999999998,"y":0,"z":0}'::jsonb, 0.15);
INSERT INTO level_objectives (level_id, code, title, objective_type, checkpoint_id, config, sort_order, required) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-15'), 'cp-1', 'Reach the damaged plank', 'REACH_CHECKPOINT', (SELECT id FROM level_checkpoints WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-15') AND code = 'cp-1'), '{}'::jsonb, 1, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-15'), 'goal', 'Stop on the tower pad', 'REACH_GOAL', NULL, '{}'::jsonb, 2, TRUE),
