INSERT INTO level_hints (level_id, title, content, cost, sort_order) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-15'), 'Hint 1', 'Distance to the plank = 60 + segments × 40. Keep it in a variable — you need it twice.', 0, 1),
  ((SELECT id FROM levels WHERE slug = 'starter-15'), 'Hint 2', 'set d to (mission.segments × 40 + 60) → move forward d → wait → move forward (420 − d).', 0, 2),
  ((SELECT id FROM levels WHERE slug = 'starter-15'), 'Hint 3', 'set d to ((mission segments × 40) + 60) → move forward (d) → wait 2 → move forward (? − d).', 0, 3),
  ((SELECT id FROM levels WHERE slug = 'starter-15'), 'Hint 4', 'set d to ((mission segments × 40) + 60) → move forward (d) → wait 2 → move forward (420 − d).', 10, 4);

INSERT INTO level_checkpoints (level_id, code, name, sort_order, position, radius) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-16'), 'cp-1', 'Deliver to the target station', 1, '{"x":-1.5999999999999999,"y":0,"z":0}'::jsonb, 0.18);
INSERT INTO level_objectives (level_id, code, title, objective_type, checkpoint_id, config, sort_order, required) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-16'), 'cp-1', 'Deliver to the target station', 'REACH_CHECKPOINT', (SELECT id FROM level_checkpoints WHERE level_id = (SELECT id FROM levels WHERE slug = 'starter-16') AND code = 'cp-1'), '{}'::jsonb, 1, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-16'), 'goal', 'Stop on the dispatch pad', 'REACH_GOAL', NULL, '{}'::jsonb, 2, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-16'), 'safe', 'Don’t hit any obstacles', 'AVOID_COLLISIONS', NULL, '{"maxCollisions":0}'::jsonb, 3, TRUE);
INSERT INTO level_hints (level_id, title, content, cost, sort_order) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-16'), 'Hint 1', 'The stations are 80 cm apart: station 3 is 3 × 80 cm from the pad. Store that distance in a variable — the way back is the same distance.', 0, 1),
  ((SELECT id FROM levels WHERE slug = 'starter-16'), 'Hint 2', 'd = mission.target × 80 → drive d → turn left → into the bay and back out → turn right → drive back d.', 0, 2),
  ((SELECT id FROM levels WHERE slug = 'starter-16'), 'Hint 3', 'd = mission.target * 80
robot.move_forward(d)
robot.turn_left(90)
robot.move_forward(60)
robot.move_backward(60)
robot.turn_right(90)
robot.move_backward(?)', 0, 3),
  ((SELECT id FROM levels WHERE slug = 'starter-16'), 'Hint 4', 'd = mission.target * 80
robot.move_forward(d)
robot.turn_left(90)
robot.move_forward(60)
robot.move_backward(60)
robot.turn_right(90)
robot.move_backward(d)', 10, 4);

INSERT INTO level_objectives (level_id, code, title, objective_type, checkpoint_id, config, sort_order, required) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-17'), 'rescue', 'Bring every pod to base', 'CUSTOM', NULL, '{"tracked":true,"kind":"deliverCargo","count":0}'::jsonb, 1, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-17'), 'safe', 'Don’t hit any obstacles', 'AVOID_COLLISIONS', NULL, '{"maxCollisions":0}'::jsonb, 2, TRUE);
INSERT INTO level_hints (level_id, title, content, cost, sort_order) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-17'), 'Hint 1', 'Every trip is the same except the distance: 70, 140, 210 … cm. Keep the pod number in a variable and add 1 after each trip.', 0, 1),
  ((SELECT id FROM levels WHERE slug = 'starter-17'), 'Hint 2', 'k = 1 → repeat mission.count times { drive k × 70 → turn in, pick up, back out → drive back → turn to the drop zone, drop, turn back → k = k + 1 }.', 0, 2),
  ((SELECT id FROM levels WHERE slug = 'starter-17'), 'Hint 3', 'k = 1
for _ in range(mission.count):
    robot.move_forward(k * 70)
    robot.turn_left(90)
    robot.move_forward(30)
    robot.pick_up()
    robot.move_backward(30)
    robot.turn_right(90)
    robot.move_backward(k * 70)
    … drop at base …
    k += 1', 0, 3),
  ((SELECT id FROM levels WHERE slug = 'starter-17'), 'Hint 4', 'k = 1
for _ in range(mission.count):
    robot.move_forward(k * 70)
    robot.turn_left(90)
    robot.move_forward(30)
    robot.pick_up()
    robot.move_backward(30)
    robot.turn_right(90)
    robot.move_backward(k * 70)
    robot.turn_right(90)
    robot.drop()
    robot.turn_left(90)
    k += 1', 10, 4);

INSERT INTO level_objectives (level_id, code, title, objective_type, checkpoint_id, config, sort_order, required) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-18'), 'goal', 'Park in the first free bay', 'REACH_GOAL', NULL, '{}'::jsonb, 1, TRUE),
