INSERT INTO level_hints (level_id, title, content, cost, sort_order) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-18'), 'Hint 1', 'You don’t know how many bays you’ll have to check: loop forever and break out as soon as you find a free one.', 0, 1),
  ((SELECT id FROM levels WHERE slug = 'starter-18'), 'Hint 2', 'drive to bay 1 → while True { turn towards the bay; if it is free → break; turn back; drive to the next bay } → drive in.', 0, 2),
  ((SELECT id FROM levels WHERE slug = 'starter-18'), 'Hint 3', 'robot.move_forward(70)
while True:
    robot.turn_left(90)
    if robot.distance() > 60:
        break
    robot.turn_right(90)
    robot.move_forward(?)
robot.move_forward(?)', 0, 3),
  ((SELECT id FROM levels WHERE slug = 'starter-18'), 'Hint 4', 'robot.move_forward(70)
while True:
    robot.turn_left(90)
    if robot.distance() > 60:
        break
