INSERT INTO level_hints (level_id, title, content, cost, sort_order) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-19'), 'Hint 1', 'A negative distance makes the robot drive backwards — so “target − position” works whichever side the target is on.', 0, 1),
  ((SELECT id FROM levels WHERE slug = 'starter-19'), 'Hint 2', 'face right → drive x1 − x → turn left (face up) → drive y1 − y → turn right → drive x2 − x → turn left → drive y2 − y → back to the depot the same way.', 0, 2),
  ((SELECT id FROM levels WHERE slug = 'starter-19'), 'Hint 3', 'robot.move_forward(mission.x1 - robot.x())
robot.turn_left(90)
robot.move_forward(mission.y1 - robot.y())
robot.turn_right(90)
… point 2 the same way …
robot.move_forward(-240 - robot.x())
robot.turn_left(90)
robot.move_forward(-140 - robot.y())', 0, 3),
  ((SELECT id FROM levels WHERE slug = 'starter-19'), 'Hint 4', 'robot.move_forward(mission.x1 - robot.x())
robot.turn_left(90)
robot.move_forward(mission.y1 - robot.y())
robot.turn_right(90)
robot.move_forward(mission.x2 - robot.x())
robot.turn_left(90)
robot.move_forward(mission.y2 - robot.y())
robot.turn_right(90)
robot.move_forward(-240 - robot.x())
robot.turn_left(90)
robot.move_forward(-140 - robot.y())', 10, 4);

