INSERT INTO level_objectives (level_id, code, title, objective_type, checkpoint_id, config, sort_order, required) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-20'), 'all-cp', 'Evacuate every village at risk', 'REACH_ALL_CHECKPOINTS', NULL, '{}'::jsonb, 1, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-20'), 'goal', 'Reach the storm shelter', 'REACH_GOAL', NULL, '{}'::jsonb, 2, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-20'), 'safe', 'Don’t hit any obstacles', 'AVOID_COLLISIONS', NULL, '{"maxCollisions":0}'::jsonb, 3, TRUE);
INSERT INTO level_hints (level_id, title, content, cost, sort_order) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-20'), 'Hint 1', 'Each village needs the same test with its own numbers: mission.risk_a and mission.people_a for A, and so on. Both parts must be true — “and”.', 0, 1),
  ((SELECT id FROM levels WHERE slug = 'starter-20'), 'Hint 2', 'drive to A → if risk_a > 5 and people_a > 0 → (into the village and back out) → drive to B → same test → drive to C → same test → drive to the shelter.', 0, 2),
  ((SELECT id FROM levels WHERE slug = 'starter-20'), 'Hint 3', 'robot.move_forward(100)
if mission.risk_a > 5 and mission.people_a > 0:
    robot.turn_left(90)
    robot.move_forward(60)
    robot.move_backward(60)
    robot.turn_right(90)
robot.move_forward(120)
… B and C the same …
robot.move_forward(?)', 0, 3),
  ((SELECT id FROM levels WHERE slug = 'starter-20'), 'Hint 4', 'robot.move_forward(100)
if mission.risk_a > 5 and mission.people_a > 0:
    (in and out of the village)
robot.move_forward(120)
if mission.risk_b > 5 and mission.people_b > 0:
    (in and out)
robot.move_forward(120)
if mission.risk_c > 5 and mission.people_c > 0:
    (in and out)
robot.move_forward(125)   — “in and out” = turn_left(90), move_forward(60), move_backward(60), turn_right(90)', 10, 4);

INSERT INTO level_objectives (level_id, code, title, objective_type, checkpoint_id, config, sort_order, required) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-21'), 'deliver', 'Deliver 10 parts to the right lines', 'CUSTOM', NULL, '{"tracked":true,"kind":"deliverCargo","count":10}'::jsonb, 1, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-21'), 'goal', 'Park at the charger', 'REACH_GOAL', NULL, '{}'::jsonb, 2, TRUE),
  ((SELECT id FROM levels WHERE slug = 'starter-21'), 'safe', 'Don’t hit any obstacles', 'AVOID_COLLISIONS', NULL, '{"maxCollisions":0}'::jsonb, 3, TRUE);
INSERT INTO level_hints (level_id, title, content, cost, sort_order) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-21'), 'Hint 1', 'Without functions this program would be over 100 blocks. Each kind of delivery is always the same moves — give each a name.', 0, 1),
  ((SELECT id FROM levels WHERE slug = 'starter-21'), 'Hint 2', 'def to_motors(): (pick up, carry east, drop, come back) · def to_sensors(): (pick up, carry south, drop, come back) · repeat 10 { if red → to_motors() else → to_sensors() }.', 0, 2),
  ((SELECT id FROM levels WHERE slug = 'starter-21'), 'Hint 3', 'def to_motors():
    robot.pick_up()
    robot.turn_right(180)
    robot.move_forward(170)
    robot.drop()
    robot.turn_left(180)
    robot.move_forward(170)

def to_sensors():
    …

for _ in range(10):
    if robot.color() == "red":
        to_motors()
    else:
        to_sensors()', 0, 3),
  ((SELECT id FROM levels WHERE slug = 'starter-21'), 'Hint 4', 'def to_motors():
    robot.pick_up(); robot.turn_right(180); robot.move_forward(170); robot.drop(); robot.turn_left(180); robot.move_forward(170)
def to_sensors():
    robot.pick_up(); robot.turn_left(90); robot.move_forward(120); robot.drop(); robot.move_backward(120); robot.turn_right(90)
robot.set_speed(100)
for _ in range(10): if red → to_motors() else → to_sensors()
robot.turn_right(90)
robot.move_forward(120)   (one instruction per line in your program)', 10, 4);

