INSERT INTO level_hints (level_id, title, content, cost, sort_order) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-23'), 'Hint 1', 'Split the job into parts and solve one at a time. robot.go_to(x, y) drives straight to a point — handy to get round the map (y is up, in cm).', 0, 1),
  ((SELECT id FROM levels WHERE slug = 'starter-23'), 'Hint 2', 'push the block (forward 100, turn left, forward 140, back 140) → drive east to the shelf → twice: pick up, carry north to the depot, drop, come back → go to the stop line → wait until green → drive to the tower.', 0, 2),
  ((SELECT id FROM levels WHERE slug = 'starter-23'), 'Hint 3', 'The shelf is 140 cm east of the block lane, the depot 205 cm north of the shelf lane, the stop line is at (78, 65). Wait for green — yellow is too late to start: while robot.color() != "green": robot.wait(0.1)', 0, 3),
  ((SELECT id FROM levels WHERE slug = 'starter-23'), 'Hint 4', 'forward 100 · left 90 · forward 140 · backward 140 · right 90 · forward 140 · pick_up · left 90 · forward 205 · drop · backward 205 · right 90 · pick_up · left 90 · forward 205 · drop · go_to(78, 65) · while robot.color() != "green": wait(0.1) · forward 152', 10, 4);

