INSERT INTO level_hints (level_id, title, content, cost, sort_order) VALUES
  ((SELECT id FROM levels WHERE slug = 'starter-24'), 'Hint 1', 'A cart is dangerous when it comes from the side — the sensor can’t see it there. Wait until it has passed in FRONT of the robot: then you know where it is and how long it needs to come back.', 0, 1),
  ((SELECT id FROM levels WHERE slug = 'starter-24'), 'Hint 2', 'drive to the line before track 1 → wait while nothing is in front → wait while the cart is in front → cross at full speed → the same for track 2 → pick up the survivor → Hospital Street → wait for green → drive to the hospital and drop.', 0, 2),
  ((SELECT id FROM levels WHERE slug = 'starter-24'), 'Hint 3', 'robot.set_speed(100)
robot.move_forward(115)
while robot.distance() > 50:
    robot.wait(0.1)
while robot.distance() < 50:
    robot.wait(0.1)
robot.move_forward(160)
… track 2 the same, then forward 170 …', 0, 3),
  ((SELECT id FROM levels WHERE slug = 'starter-24'), 'Hint 4', 'robot.set_speed(100) · forward 115 · (wait while distance > 50, wait while distance < 50) · forward 160 · (the same two waits) · forward 170 · pick_up · backward 25 · turn_left 90 · forward 110 · while robot.color() != "green": wait(0.1) · forward 175 · drop', 10, 4);

