  ('Bridge Builder',     'bridge-builder',     'Cross the canyon bridge.',                               'bridge', 40,  '{"type":"complete_level","level":"canyon-03"}', 5, 'PUBLISHED'),
  ('Star Collector',     'star-collector',     'Earn 15 stars.',                                         'star', 50,    '{"type":"total_stars","count":15}', 6, 'PUBLISHED'),
  ('Perfect Programmer', 'perfect-programmer', 'Earn 3 stars on 5 different missions.',                  'sparkles', 60, '{"type":"three_star_levels","count":5}', 7, 'PUBLISHED'),
  ('Three-Day Streak',   'streak-3',           'Practise on three days in a row.',                       'flame', 25,   '{"type":"streak_days","count":3}', 8, 'PUBLISHED');

