-- -----------------------------------------------------------------------------
-- Lessons
-- -----------------------------------------------------------------------------
INSERT INTO lessons (curriculum_id, world_id, level_id, title, slug, description, content_type, content, sort_order, status)
SELECT c.id, w.id, l.id, x.title, x.slug, x.description, x.content_type::lesson_content_type, x.content::jsonb, x.sort_order, 'PUBLISHED'
  FROM (VALUES
    ('robotics-foundations', 'starter-island', NULL, 'What is a program?', 'what-is-a-program',
     'Programs are lists of instructions a robot follows from top to bottom.', 'MARKDOWN',
     '{"markdown":"# What is a program?\n\nA **program** is a list of instructions. Your robot reads them **from top to bottom**, one at a time.\n\n1. Every program starts with *when program starts*.\n2. Snap blocks underneath it.\n3. Press **Run** and watch the robot follow your plan."}', 1),
    ('robotics-foundations', 'starter-island', 'starter-02', 'Turning on the spot', 'turning-on-the-spot',
     'The robot turns without moving forward — drive into the corner first.', 'MARKDOWN',
     '{"markdown":"## Turning on the spot\n\n*turn left 90°* rotates the robot **where it stands**. To go around a corner:\n\n- drive forward **into** the corner,\n- turn,\n- drive forward again."}', 2),
    ('robotics-foundations', 'canyon-circuit', 'canyon-01', 'Loops save time', 'loops-save-time',
     'When the same steps repeat, put them inside a repeat block.', 'INTERACTIVE',
     '{"widget":"loop-unroller","pattern":["motion.forward","motion.turnLeft","motion.forward","motion.turnRight"],"times":2}', 3),
    ('robotics-foundations', 'canyon-circuit', 'canyon-02', 'How the distance sensor works', 'distance-sensor',
     'The sensor measures how far away the nearest object is in front of the robot.', 'TEXT',
     '{"text":"The distance sensor sends an invisible beam forward and measures how far it travels before hitting something. obstacle ahead? becomes true when something is closer than 20 cm."}', 4)
  ) AS x(curriculum_slug, world_slug, level_slug, title, slug, description, content_type, content, sort_order)
  JOIN curricula c ON c.slug = x.curriculum_slug
  LEFT JOIN worlds w ON w.slug = x.world_slug
  LEFT JOIN levels l ON l.slug = x.level_slug;

-- -----------------------------------------------------------------------------
-- Sample activity (so dashboards and unlock rules have data to show)
--   nguyenvana01 : finished Starter Island (a failed try before each pass)
--   tranthib02   : finished First Steps, working on Turn the Corner
--   leminhc03    : new — an admin unlocked Staircase for them manually
-- Totals in student_stats are maintained by the XP / star ledger triggers.
-- -----------------------------------------------------------------------------
DO $$
DECLARE
  v_admin   UUID := (SELECT id FROM users WHERE username_normalized = 'admin');
  v_a       UUID := (SELECT id FROM users WHERE username_normalized = 'nguyenvana01');
  v_b       UUID := (SELECT id FROM users WHERE username_normalized = 'tranthib02');
  v_c       UUID := (SELECT id FROM users WHERE username_normalized = 'leminhc03');
  r         RECORD;
  v_level   UUID;
  v_xp      INTEGER;
  v_title   TEXT;
  v_prog    UUID;
  v_ver     program_versions;
  v_sub     UUID;
  v_when    TIMESTAMPTZ;
BEGIN
  FOR r IN SELECT * FROM (VALUES
    ('starter-01', '{"format":"roboverse.blocks","version":1,"blocks":{"b1":{"id":"b1","type":"motion.forward","fields":{"distance":170},"inputs":{"distance":null},"slots":{},"next":null},"start":{"id":"start","type":"event.start","fields":{},"inputs":{},"slots":{},"next":"b1"}},"roots":[{"id":"start","x":40,"y":28}],"variables":[]}'::jsonb, 'from roboverse import robot

robot.move_forward(170)
', 3, 5.6, 1, 4),
    ('starter-02', '{"format":"roboverse.blocks","version":1,"blocks":{"b1":{"id":"b1","type":"motion.forward","fields":{"distance":250},"inputs":{"distance":null},"slots":{},"next":"b2"},"b2":{"id":"b2","type":"motion.turnLeft","fields":{"angle":90},"inputs":{"angle":null},"slots":{},"next":"b3"},"b3":{"id":"b3","type":"motion.forward","fields":{"distance":180},"inputs":{"distance":null},"slots":{},"next":null},"start":{"id":"start","type":"event.start","fields":{},"inputs":{},"slots":{},"next":"b1"}},"roots":[{"id":"start","x":40,"y":28}],"variables":[]}'::jsonb, 'from roboverse import robot

robot.move_forward(250)
robot.turn_left(90)
robot.move_forward(180)
', 3, 16.4, 3, 3),
    ('starter-03', '{"format":"roboverse.blocks","version":1,"blocks":{"b1":{"id":"b1","type":"motion.forward","fields":{"distance":200},"inputs":{"distance":null},"slots":{},"next":"b2"},"b2":{"id":"b2","type":"motion.turnLeft","fields":{"angle":90},"inputs":{"angle":null},"slots":{},"next":"b3"},"b3":{"id":"b3","type":"motion.forward","fields":{"distance":240},"inputs":{"distance":null},"slots":{},"next":"b4"},"b4":{"id":"b4","type":"motion.turnRight","fields":{"angle":90},"inputs":{"angle":null},"slots":{},"next":"b5"},"b5":{"id":"b5","type":"motion.forward","fields":{"distance":160},"inputs":{"distance":null},"slots":{},"next":null},"start":{"id":"start","type":"event.start","fields":{},"inputs":{},"slots":{},"next":"b1"}},"roots":[{"id":"start","x":40,"y":28}],"variables":[]}'::jsonb, 'from roboverse import robot

robot.move_forward(200)
robot.turn_left(90)
robot.move_forward(240)
robot.turn_right(90)
robot.move_forward(160)
', 2, 37.9, 5, 2)
  ) AS t(slug, program, python, stars, secs, blocks, days_ago)
  LOOP
    SELECT id, xp_reward, title INTO v_level, v_xp, v_title FROM levels WHERE slug = r.slug;
    v_when := CURRENT_TIMESTAMP - make_interval(days => r.days_ago);

    INSERT INTO programs (student_id, level_id, created_at) VALUES (v_a, v_level, v_when) RETURNING id INTO v_prog;
    v_ver := save_program_version(v_prog, r.program, r.python, 'SUBMISSION');

    INSERT INTO level_attempts (student_id, level_id, program_id, status, collisions, error_message, execution_time_seconds, started_at, completed_at)
    VALUES (v_a, v_level, v_prog, 'FAILED', 1, 'The robot hit a barrier.', r.secs / 2, v_when, v_when + interval '20 seconds');

    INSERT INTO submissions (student_id, level_id, program_id, program_version_id, status, score, stars, xp_earned, execution_time_seconds, block_count, result, submitted_at, completed_at, created_at)
    VALUES (v_a, v_level, v_prog, v_ver.id, 'PASSED', 500 + 100 * r.stars, r.stars, v_xp, r.secs, r.blocks,
            jsonb_build_object('collisions', 0, 'objectivesCompleted', true), v_when + interval '2 minutes', v_when + interval '2 minutes', v_when + interval '2 minutes')
    RETURNING id INTO v_sub;

    INSERT INTO level_attempts (student_id, level_id, program_id, program_version_id, submission_id, status, score, stars, execution_time_seconds, block_count, collisions, started_at, completed_at)
    VALUES (v_a, v_level, v_prog, v_ver.id, v_sub, 'PASSED', 500 + 100 * r.stars, r.stars, r.secs, r.blocks, 0, v_when + interval '2 minutes', v_when + interval '3 minutes');

    UPDATE programs SET is_submitted = TRUE WHERE id = v_prog;

    INSERT INTO student_level_progress (student_id, level_id, status, best_score, best_stars, best_time_seconds, attempt_count, first_started_at, completed_at, last_attempt_at, last_program_id)
    VALUES (v_a, v_level, 'COMPLETED', 500 + 100 * r.stars, r.stars, r.secs, 2, v_when, v_when + interval '3 minutes', v_when + interval '3 minutes', v_prog);

    INSERT INTO student_objective_progress (student_id, objective_id, completed, completed_at)
    SELECT v_a, o.id, TRUE, v_when + interval '3 minutes' FROM level_objectives o WHERE o.level_id = v_level;

    INSERT INTO star_transactions (student_id, level_id, submission_id, stars_before, stars_after, created_at)
    VALUES (v_a, v_level, v_sub, 0, r.stars, v_when + interval '3 minutes');
    INSERT INTO xp_transactions (student_id, amount, source_type, source_id, description, created_at)
    VALUES (v_a, v_xp, 'LEVEL_COMPLETION', v_level, 'Completed ' || v_title, v_when + interval '3 minutes');
  END LOOP;

  -- Achievements for student A (and their XP).
  INSERT INTO student_achievements (student_id, achievement_id, unlocked_at, context)
  SELECT v_a, a.id, CURRENT_TIMESTAMP - interval '2 days', jsonb_build_object('source', 'seed') FROM achievements a WHERE a.slug IN ('first-steps', 'starter-graduate', 'streak-3');
  INSERT INTO xp_transactions (student_id, amount, source_type, source_id, description)
  SELECT v_a, a.xp_reward, 'ACHIEVEMENT', a.id, 'Achievement unlocked: ' || a.name FROM achievements a WHERE a.slug IN ('first-steps', 'starter-graduate', 'streak-3');
  UPDATE student_stats SET current_streak = 3, longest_streak = 3, last_active_date = CURRENT_DATE - 2 WHERE student_id = v_a;

  -- Student B: finished First Steps (2 stars), working on Turn the Corner.
  SELECT id, xp_reward INTO v_level, v_xp FROM levels WHERE slug = 'starter-01';
  INSERT INTO programs (student_id, level_id) VALUES (v_b, v_level) RETURNING id INTO v_prog;
  v_ver := save_program_version(v_prog, (SELECT block_program FROM programs p JOIN levels l ON l.id = p.level_id WHERE p.student_id = v_a AND l.slug = 'starter-01'), NULL, 'SUBMISSION');
  INSERT INTO submissions (student_id, level_id, program_id, program_version_id, status, score, stars, xp_earned, execution_time_seconds, block_count, submitted_at, completed_at)
  VALUES (v_b, v_level, v_prog, v_ver.id, 'PASSED', 700, 2, v_xp, 9.1, 2, CURRENT_TIMESTAMP - interval '1 day', CURRENT_TIMESTAMP - interval '1 day')
  RETURNING id INTO v_sub;
  INSERT INTO level_attempts (student_id, level_id, program_id, program_version_id, submission_id, status, score, stars, execution_time_seconds, block_count, collisions, started_at, completed_at)
  VALUES (v_b, v_level, v_prog, v_ver.id, v_sub, 'PASSED', 700, 2, 9.1, 2, 0, CURRENT_TIMESTAMP - interval '1 day', CURRENT_TIMESTAMP - interval '1 day' + interval '1 minute');
  INSERT INTO student_level_progress (student_id, level_id, status, best_score, best_stars, best_time_seconds, attempt_count, first_started_at, completed_at, last_attempt_at, last_program_id)
  VALUES (v_b, v_level, 'COMPLETED', 700, 2, 9.1, 1, CURRENT_TIMESTAMP - interval '1 day', CURRENT_TIMESTAMP - interval '1 day', CURRENT_TIMESTAMP - interval '1 day', v_prog);
  INSERT INTO star_transactions (student_id, level_id, submission_id, stars_before, stars_after) VALUES (v_b, v_level, v_sub, 0, 2);
  INSERT INTO xp_transactions (student_id, amount, source_type, source_id, description) VALUES (v_b, v_xp, 'LEVEL_COMPLETION', v_level, 'Completed First Steps');

  SELECT id INTO v_level FROM levels WHERE slug = 'starter-02';
  INSERT INTO programs (student_id, level_id) VALUES (v_b, v_level) RETURNING id INTO v_prog;
  v_ver := save_program_version(v_prog, '{"format":"roboverse.blocks","version":1,"blocks":{"start":{"id":"start","type":"event.start","fields":{},"inputs":{},"slots":{},"next":"b1"},"b1":{"id":"b1","type":"motion.forward","fields":{"distance":300},"inputs":{"distance":null},"slots":{},"next":null}},"roots":[{"id":"start","x":40,"y":28}],"variables":[]}'::jsonb, NULL, 'AUTOSAVE');
  INSERT INTO level_attempts (student_id, level_id, program_id, program_version_id, status, collisions, error_message, execution_time_seconds, block_count, started_at, completed_at)
  VALUES (v_b, v_level, v_prog, v_ver.id, 'FAILED', 1, 'The robot hit a barrier.', 7.8, 1, CURRENT_TIMESTAMP - interval '3 hours', CURRENT_TIMESTAMP - interval '3 hours' + interval '15 seconds');
  INSERT INTO student_level_progress (student_id, level_id, status, attempt_count, first_started_at, last_attempt_at, last_program_id)
  VALUES (v_b, v_level, 'IN_PROGRESS', 1, CURRENT_TIMESTAMP - interval '3 hours', CURRENT_TIMESTAMP - interval '3 hours', v_prog);
  INSERT INTO student_hint_usage (student_id, hint_id) SELECT v_b, h.id FROM level_hints h WHERE h.level_id = v_level AND h.sort_order = 1;

  -- Student C: an admin unlocked Staircase manually (classroom use), with an audit trail.
  SELECT id INTO v_level FROM levels WHERE slug = 'canyon-01';
  INSERT INTO student_level_access (student_id, level_id, status, override_reason, granted_by)
  VALUES (v_c, v_level, 'AVAILABLE', 'Joined the club late; already knows sequences from class.', v_admin);

  INSERT INTO audit_logs (admin_id, action, entity_type, entity_id, old_data, new_data) VALUES
    (v_admin, 'CREATE_STUDENT', 'user', v_a::text, NULL, jsonb_build_object('username', 'nguyenvana01')),
    (v_admin, 'CREATE_STUDENT', 'user', v_b::text, NULL, jsonb_build_object('username', 'tranthib02')),
    (v_admin, 'CREATE_STUDENT', 'user', v_c::text, NULL, jsonb_build_object('username', 'leminhc03')),
    (v_admin, 'PUBLISH_LEVEL', 'level', (SELECT id FROM levels WHERE slug = 'canyon-03')::text, jsonb_build_object('status', 'DRAFT'), jsonb_build_object('status', 'PUBLISHED')),
    (v_admin, 'UNLOCK_LEVEL', 'student_level_access', v_level::text,
     jsonb_build_object('student', 'leminhc03', 'state', 'LOCKED'),
     jsonb_build_object('student', 'leminhc03', 'state', 'AVAILABLE', 'reason', 'Joined the club late; already knows sequences from class.'));
END;
$$;

COMMIT;
